// ─── Supabase (config isolée dans config.js, saisie partagée multi-appareil) ───
let sbClient=null;
function initSupabaseClient(){
  if(sbClient) return sbClient;
  if(typeof SUPABASE_URL==="undefined"||typeof supabase==="undefined") return null;
  sbClient=supabase.createClient(SUPABASE_URL,SUPABASE_ANON_KEY);
  return sbClient;
}
initSupabaseClient();

async function checkAuthSession(){
  const client=initSupabaseClient();
  if(!client){ S.authOk=true; R(); return; } // Supabase indisponible : ne jamais bloquer l'usage local
  try{
    const {data}=await client.auth.getSession();
    S.authOk=!!(data&&data.session);
  }catch(e){
    S.authOk=true; // fail-open : jamais bloquer l'usage local sur une erreur réseau/API
  }
  // Tant qu'aucun profil d'equipe n'est connu (1er lancement sur cet appareil), impossible de
  // filtrer correctement par team_profile — l'ecran de choix (STORY-51) prend le relais. Une fois
  // le profil choisi, PAS de rattrapage ici volontairement (retour Romain : cliquer -18/CF ne
  // doit jamais etre interrompu par une proposition de reprise) — le prochain vrai chargement
  // de page sur cet appareil (deja configure) refera ce test normalement.
  if(S.authOk && S.teamProfile) await checkForResumableMatch();
  R();
}

async function signInShared(password){
  const client=initSupabaseClient();
  if(!client){ S.authOk=true; R(); return; }
  S.authError=null;
  const {error}=await client.auth.signInWithPassword({email:SUPABASE_AUTH_EMAIL,password});
  if(error){ S.authError="Code d'accès incorrect."; R(); return; }
  S.authOk=true;
  if(S.teamProfile) await checkForResumableMatch(); // uniquement si le profil est deja connu sur cet appareil
  R();
}

// ─── Reprise de match sur un autre appareil — STORY-14 ───
async function fetchInProgressMatches(){
  const client=initSupabaseClient();
  if(!client) return [];
  try{
    const {data,error}=await client.from('matches').select('*').eq('status','in_progress').eq('team_profile',S.teamProfile||"cf").order('updated_at',{ascending:false});
    if(error||!data) return [];
    return data;
  }catch(e){ return []; }
}

async function checkForResumableMatch(){
  if(S.currentMatchId) return; // cet appareil a déjà un match actif cette session, ne pas proposer d'en reprendre un autre
  const matches=await fetchInProgressMatches();
  if(matches.length>0) S.resumePrompt=matches;
}

async function resumeMatch(matchId){
  const client=initSupabaseClient();
  if(!client) return;
  try{
    const {data:match,error:matchErr}=await client.from('matches').select('*').eq('id',matchId).single();
    if(matchErr||!match) return;
    const {data:events,error:evErr}=await client.from('match_events').select('*').eq('match_id',matchId);
    S.home.name=match.home_name||"FENIX Toulouse";
    S.away.name=match.away_name||"Adversaire";
    S.home.players=match.home_roster||[];
    S.away.players=match.away_roster||[];
    S.home.gkId=match.home_gk_id||null;
    S.away.gkId=match.away_gk_id||null;
    S.period=match.period||1;
    S.time=match.time_offset_seconds||0;
    if(match.running && match.last_start_at){
      const elapsed=Math.floor((Date.now()-new Date(match.last_start_at).getTime())/1000);
      S.time+=Math.max(0,elapsed);
    }
    S.events=(evErr||!events?[]:events).map(supabaseRowToEvent).sort((a,b)=>
      (b.period-a.period) || (b.rawTime-a.rawTime)
    );
    S.currentMatchId=matchId;
    S.resumePrompt=null;
    S.view="match";
    subscribeMatchEvents(matchId);
    if(match.running) startTimer(); else R();
  }catch(e){ /* best-effort — en cas d'échec, laisser l'écran de reprise affiché pour réessayer */ }
}

function dismissResumePrompt(){
  S.resumePrompt=null;
  R();
}

// ─── Rapatriement de l'historique archivé depuis un autre appareil — STORY-48 ───
// Contrairement a fetchInProgressMatches() (matchs EN COURS, pour la reprise), ceci couvre les
// matchs deja TERMINES ("finished") — jamais rapatries avant cette story : renderHistory()/
// renderBilan() ne lisaient jusqu'ici que dbGetAll() (IndexedDB, strictement local a l'appareil).
async function fetchMissingArchivedMatches(localMatches){
  const client=initSupabaseClient();
  if(!client) return [];
  const known=new Set(localMatches.map(m=>m.supabaseMatchId).filter(Boolean));
  try{
    const {data,error}=await client.from('matches').select('*').eq('status','finished').eq('team_profile',S.teamProfile||"cf").order('updated_at',{ascending:false});
    if(error||!data) return [];
    return data.filter(row=>!known.has(row.id));
  }catch(e){ return []; }
}
async function importArchivedMatch(row, idOffset){
  const client=initSupabaseClient();
  if(!client) return null;
  try{
    const {data:events}=await client.from('match_events').select('*').eq('match_id',row.id);
    const evts=(events||[]).map(supabaseRowToEvent).sort((a,b)=>(b.period-a.period)||(b.rawTime-a.rawTime));
    const scoreH=evts.filter(e=>e.team==="home"&&ACTIONS[e.type]?.isGoal).length;
    const scoreA=evts.filter(e=>e.team==="away"&&ACTIONS[e.type]?.isGoal).length;
    return {
      id:Date.now()+idOffset, // evite toute collision si plusieurs imports dans la meme boucle synchrone
      date:row.updated_at?new Date(row.updated_at).toLocaleDateString("fr-FR",{day:"numeric",month:"short",year:"numeric",hour:"2-digit",minute:"2-digit"}):"",
      season:row.season||"", journee:row.journee||"", championnat:row.championnat||"",
      teamProfile:row.team_profile||"cf",
      home:{name:row.home_name||"FENIX Toulouse", players:row.home_roster||[], gkId:row.home_gk_id||null},
      away:{name:row.away_name||"Adversaire", players:row.away_roster||[], gkId:row.away_gk_id||null},
      events:evts, time:row.time_offset_seconds||0, period:row.period||2,
      scoreH, scoreA, coachNotes:row.coach_notes||"",
      supabaseMatchId:row.id,
    };
  }catch(e){ return null; }
}
// Boucle sequentielle (pas Promise.all) : evite une rafale de requetes simultanees vers Supabase
// si beaucoup de matchs sont a rapatrier (1ere ouverture de l'ecran sur un nouvel appareil).
async function syncArchivedMatchesIntoLocal(){
  const local=await dbGetAll().catch(()=>[]);
  const missing=await fetchMissingArchivedMatches(local);
  if(missing.length===0) return 0;
  let imported=0;
  for(let i=0;i<missing.length;i++){
    const m=await importArchivedMatch(missing[i], i);
    if(m){ await dbSaveMatch(m).catch(()=>{}); imported++; }
  }
  return imported;
}

async function signOutShared(){
  const client=initSupabaseClient();
  if(client){ try{ await client.auth.signOut(); }catch(e){} }
  S.authOk=false;
  S.authError=null;
  R();
}

// ─── Synchronisation sortante (outbox) — STORY-12 ───
// Convertit un événement local (camelCase) vers les colonnes match_events (snake_case).
// Note : le schéma Supabase a deux colonnes numériques ("time" et "raw_time") alors que
// l'événement local n'a qu'une seule valeur numérique exploitable (rawTime — "time" local
// est une chaîne formatée "MM:SS", incompatible avec une colonne int). Les deux colonnes
// reçoivent donc la même valeur numérique (rawTime).
function eventToSupabaseRow(event,matchId){
  return {
    id:event.id, match_id:matchId, type:event.type, team:event.team,
    time:event.rawTime, raw_time:event.rawTime, period:event.period,
    x:event.x, y:event.y, gk_id:event.gkId,
    player_id:event.playerId, player_name:event.playerName, player_number:event.playerNumber,
    assist_id:event.assistId, assist_name:event.assistName, assist_number:event.assistNumber,
    goal_zone:event.goalZone
  };
}

let matchRegisteredThisSession=false;
// Snapshot complet du match (effectifs, GB, période, chrono) — pas juste la ligne minimale
// nécessaire à la contrainte de clé étrangère. Nécessaire pour qu'un autre appareil puisse
// "reprendre" ce match (STORY-14) sans avoir à ressaisir les équipes.
async function upsertMatchSnapshot(){
  const client=initSupabaseClient();
  if(!client||!S.currentMatchId) return;
  try{
    const {error}=await client.from('matches').upsert({
      id:S.currentMatchId, status:'in_progress', team_profile:S.teamProfile||"cf",
      home_name:S.home.name, away_name:S.away.name,
      home_roster:S.home.players, away_roster:S.away.players,
      home_gk_id:S.home.gkId, away_gk_id:S.away.gkId,
      period:S.period, time_offset_seconds:S.time,
      running:S.running, last_start_at:S.running?new Date().toISOString():null,
      updated_at:new Date().toISOString()
    });
    if(!error) matchRegisteredThisSession=true;
  }catch(e){ /* best-effort, retenté au prochain flush/changement */ }
}
async function ensureMatchRegistered(){ return upsertMatchSnapshot(); }

async function queueEventForSync(event){
  if(!S.currentMatchId){
    S.currentMatchId=gid();
    subscribeMatchEvents(S.currentMatchId);
  }
  try{
    await outboxPut(eventToSupabaseRow(event,S.currentMatchId));
  }catch(e){ /* la file d'attente est best-effort : ne jamais faire perdre l'événement local */ }
  flushOutbox();
}

// Annulation (undo) : retire l'événement de la file d'attente s'il n'était pas encore synchronisé,
// et tente sa suppression sur Supabase au cas où il l'était déjà — best-effort, non rejoué si hors-ligne
// (cf. notes Developer STORY-12 : limite connue, pas couverte par un mécanisme de retry dédié).
async function dequeueEventSync(event){
  if(!event) return;
  try{ await outboxDelete(event.id); await refreshSyncPendingCount(); patchSyncIndicator(); }catch(e){}
  const client=initSupabaseClient();
  if(!client) return;
  try{ await client.from('match_events').delete().eq('id',event.id); }catch(e){}
}

let flushInProgress=false;
// STORY-15 : nombre d'événements en attente d'envoi, pour l'indicateur ✓/↻/⚠ — best-effort,
// jamais utilisé pour bloquer/retenter quoi que ce soit, uniquement affiché.
let syncPendingCount=0;
async function refreshSyncPendingCount(){
  try{ syncPendingCount=(await outboxGetAll()).length; }catch(e){}
}
refreshSyncPendingCount();
async function flushOutbox(){
  if(flushInProgress) return;
  const client=initSupabaseClient();
  if(!client) return;
  flushInProgress=true;
  try{
    const pending=await outboxGetAll();
    syncPendingCount=pending.length;
    if(pending.length===0) return;
    if(!matchRegisteredThisSession) await ensureMatchRegistered();
    for(const row of pending){
      try{
        const {error}=await client.from('match_events').upsert(row);
        if(!error){ await outboxDelete(row.id); syncPendingCount=Math.max(0,syncPendingCount-1); }
      }catch(e){ /* réseau indisponible, retenté au prochain flush */ }
    }
  }catch(e){
    /* best-effort */
  }finally{
    flushInProgress=false;
    patchSyncIndicator();
  }
}
window.addEventListener('online',()=>{
  flushOutbox();
  if(S.currentMatchId) subscribeMatchEvents(S.currentMatchId); // re-abonnement défensif si le canal realtime a été coupé
  patchSyncIndicator();
});
window.addEventListener('offline',()=>{ patchSyncIndicator(); });
setInterval(()=>flushOutbox(),15000);

// STORY-15 : indicateur discret ✓ sync / ↻ envoi en cours / ⚠ hors-ligne
const SYNC_STATUS_CFG={
  synced:{icon:"✓",label:"sync",color:"var(--fenix-sky)"},
  syncing:{icon:"↻",label:"envoi…",color:"var(--yellow)"},
  offline:{icon:"⚠",label:"hors-ligne",color:"var(--red)"}
};
function computeSyncStatus(){
  if(!sbClient) return null; // pas de sync configurée : pas d'indicateur
  if(!navigator.onLine) return "offline";
  if(flushInProgress || syncPendingCount>0) return "syncing";
  return "synced";
}
// Patch DOM ciblé (comme renderTimer()) plutôt qu'un R() complet : évite de perdre le focus
// d'un champ texte en cours de saisie ailleurs dans l'app à chaque cycle de flush (toutes les 15s).
function patchSyncIndicator(){
  const el=document.querySelector(".sync-indicator");
  if(!el) return;
  const st=computeSyncStatus();
  if(!st) return;
  const cfg=SYNC_STATUS_CFG[st];
  el.className=`sync-indicator sync-${st}`;
  el.style.color=cfg.color;
  el.title=`Synchronisation : ${cfg.label}`;
  el.textContent=`${cfg.icon} ${cfg.label}`;
}
function renderSyncIndicator(){
  const st=computeSyncStatus();
  if(!st) return "";
  const cfg=SYNC_STATUS_CFG[st];
  return `<span class="sync-indicator sync-${st}" style="font-size:10px;font-weight:700;color:${cfg.color};white-space:nowrap;" title="Synchronisation : ${cfg.label}">${cfg.icon} ${cfg.label}</span>`;
}

// ─── Synchronisation entrante (temps réel) — STORY-13 ───
function supabaseRowToEvent(row){
  return {
    id:row.id, type:row.type, team:row.team,
    time:fmtTime(row.raw_time||0), rawTime:row.raw_time,
    period:row.period, x:row.x, y:row.y, gkId:row.gk_id,
    playerId:row.player_id, playerName:row.player_name, playerNumber:row.player_number,
    assistId:row.assist_id, assistName:row.assist_name, assistNumber:row.assist_number,
    goalZone:row.goal_zone
  };
}

function mergeRemoteEvent(row){
  const incoming=supabaseRowToEvent(row);
  const existingIdx=S.events.findIndex(e=>e.id===incoming.id);
  if(existingIdx!==-1){
    // Événement déjà connu localement (propre écho, ou correction faite ailleurs) : mise à jour en place, pas de doublon
    S.events[existingIdx]=incoming;
  } else {
    // Insertion à la bonne position chronologique (index 0 = le plus récent, cf. usages de S.events[0] dans le reste de l'app)
    const insertIdx=S.events.findIndex(e=>
      e.period<incoming.period || (e.period===incoming.period && e.rawTime<incoming.rawTime)
    );
    if(insertIdx===-1) S.events.push(incoming);
    else S.events.splice(insertIdx,0,incoming);
  }
  R();
}

let realtimeChannel=null;
// Fusionne l'état "match" reçu en temps réel (période, chrono) — sans ça, le chrono d'un
// appareil ne se met jamais à jour après la reprise initiale, seuls les événements le font.
function mergeRemoteMatchSnapshot(row){
  if(!row) return;
  const wasRunning=S.running;
  S.period=row.period||S.period;
  if(row.running && row.last_start_at){
    const elapsed=Math.floor((Date.now()-new Date(row.last_start_at).getTime())/1000);
    S.time=(row.time_offset_seconds||0)+Math.max(0,elapsed);
    if(!wasRunning){ S.running=true; timerInterval=setInterval(()=>{S.time++;renderTimer();},1000); }
  } else {
    S.time=row.time_offset_seconds||0;
    if(wasRunning){ S.running=false; clearInterval(timerInterval); }
  }
  R();
}

function subscribeMatchEvents(matchId){
  const client=initSupabaseClient();
  if(!client||!matchId) return;
  if(realtimeChannel){ try{ client.removeChannel(realtimeChannel); }catch(e){} realtimeChannel=null; }
  realtimeChannel=client.channel('match_events_'+matchId)
    .on('postgres_changes',{event:'*',schema:'public',table:'match_events',filter:'match_id=eq.'+matchId},(payload)=>{
      if(payload.eventType==='DELETE'){
        const idx=S.events.findIndex(e=>e.id===(payload.old&&payload.old.id));
        if(idx!==-1){ S.events.splice(idx,1); R(); }
        return;
      }
      mergeRemoteEvent(payload.new);
    })
    .on('postgres_changes',{event:'UPDATE',schema:'public',table:'matches',filter:'id=eq.'+matchId},(payload)=>{
      mergeRemoteMatchSnapshot(payload.new);
    })
    .subscribe();
}
function unsubscribeMatchEvents(){
  if(!realtimeChannel) return;
  const client=initSupabaseClient();
  if(client){ try{ client.removeChannel(realtimeChannel); }catch(e){} }
  realtimeChannel=null;
}

// ─── IndexedDB for match history ───
const DB_NAME="fenix_stats"; const DB_VER=2; const STORE="matches"; const OUTBOX_STORE="pendingSync";
let db=null;
function openDB(){
  return new Promise((resolve,reject)=>{
    if(db){resolve(db);return;}
    const req=indexedDB.open(DB_NAME,DB_VER);
    req.onupgradeneeded=e=>{
      const d=e.target.result;
      if(!d.objectStoreNames.contains(STORE)){
        const s=d.createObjectStore(STORE,{keyPath:"id"});
        s.createIndex("date","date");
        s.createIndex("season","season");
      }
      if(!d.objectStoreNames.contains(OUTBOX_STORE)){
        d.createObjectStore(OUTBOX_STORE,{keyPath:"id"});
      }
    };
    req.onsuccess=e=>{db=e.target.result;resolve(db);};
    req.onerror=e=>reject(e.target.error);
  });
}
async function dbSaveMatch(match){
  const d=await openDB();
  return new Promise((res,rej)=>{
    const tx=d.transaction(STORE,"readwrite");
    tx.objectStore(STORE).put(match);
    tx.oncomplete=()=>res();
    tx.onerror=e=>rej(e.target.error);
  });
}
async function dbGetAll(){
  const d=await openDB();
  return new Promise((res,rej)=>{
    const tx=d.transaction(STORE,"readonly");
    const req=tx.objectStore(STORE).getAll();
    req.onsuccess=()=>res(req.result.sort((a,b)=>b.id-a.id));
    req.onerror=e=>rej(e.target.error);
  });
}
async function dbDelete(id){
  const d=await openDB();
  return new Promise((res,rej)=>{
    const tx=d.transaction(STORE,"readwrite");
    tx.objectStore(STORE).delete(id);
    tx.oncomplete=()=>res();
    tx.onerror=e=>rej(e.target.error);
  });
}
// ─── Outbox (file d'attente de sync Supabase, persistée pour survivre à un reload) ───
async function outboxPut(item){
  const d=await openDB();
  return new Promise((res,rej)=>{
    const tx=d.transaction(OUTBOX_STORE,"readwrite");
    tx.objectStore(OUTBOX_STORE).put(item);
    tx.oncomplete=()=>res();
    tx.onerror=e=>rej(e.target.error);
  });
}
async function outboxGetAll(){
  const d=await openDB();
  return new Promise((res,rej)=>{
    const tx=d.transaction(OUTBOX_STORE,"readonly");
    const req=tx.objectStore(OUTBOX_STORE).getAll();
    req.onsuccess=()=>res(req.result);
    req.onerror=e=>rej(e.target.error);
  });
}
async function outboxDelete(id){
  const d=await openDB();
  return new Promise((res,rej)=>{
    const tx=d.transaction(OUTBOX_STORE,"readwrite");
    tx.objectStore(OUTBOX_STORE).delete(id);
    tx.oncomplete=()=>res();
    tx.onerror=e=>rej(e.target.error);
  });
}
// Migrate old localStorage matches to IndexedDB
async function migrateOldMatches(){
  try{
    const old=JSON.parse(localStorage.getItem("hb2_matches"))||[];
    if(old.length>0){
      for(const m of old) await dbSaveMatch(m);
      localStorage.removeItem("hb2_matches");
    }
  }catch(e){}
}
openDB().then(()=>migrateOldMatches());

// ─── IMPORT / EXPORT CSV ───
function parseCSVPlayers(text){
  const lines = text.trim().split("\n").filter(l=>l.trim());
  const players = [];
  lines.forEach((line,i)=>{
    const parts = line.split(/[,;\t]/).map(s=>s.trim());
    if(parts.length<2) return;
    // Ignore une éventuelle ligne d'en-tête (ex: fichier ré-importé après un export "Numéro,Nom,Poste")
    if(i===0){
      const h=parts[0].toLowerCase();
      if(h==="numéro"||h==="numero"||h==="nom"||h==="n°"||h==="no") return;
    }
    let num="", name="", pos="DC";
    if(parts.length===2){
      name=parts[0]; pos=parts[1].toUpperCase();
      if(!POSITIONS.includes(pos)){ pos="DC"; }
    } else {
      num=parts[0]; name=parts[1]; pos=(parts[2]||"DC").toUpperCase();
      if(!POSITIONS.includes(pos)){ pos="DC"; }
    }
    players.push({id:gid(), name:name||"?", number:num, position:pos, photo:null, selected:false});
  });
  return players;
}

function importFromCSVFile(side){
  const inp = document.createElement("input");
  inp.type="file"; inp.accept=".csv,.txt,.xlsx";
  inp.style.display="none";
  document.body.appendChild(inp);
  inp.onchange=()=>{
    const f=inp.files[0]; if(!f){ document.body.removeChild(inp); return; }
    const r=new FileReader();
    r.onload=e=>{
      const players=parseCSVPlayers(e.target.result);
      if(players.length===0){ safeAlert("Aucun joueur trouvé. Format: Numéro,Nom,Poste"); document.body.removeChild(inp); return; }
      S[side].players=players;
      const gbs=players.filter(p=>p.position==="GB");
      if(gbs.length>0) S[side].gkId=gbs[0].id;
      saveTeams(); R();
      safeAlert(players.length+" joueurs importés !");
      document.body.removeChild(inp);
    };
    r.readAsText(f);
  };
  inp.click();
}

function importFromText(side, text){
  const players=parseCSVPlayers(text);
  if(players.length===0){ safeAlert("Aucun joueur trouvé. Format:\nNom,Poste\nou\nNuméro,Nom,Poste"); return; }
  S[side].players=players;
  const gbs=players.filter(p=>p.position==="GB");
  if(gbs.length>0) S[side].gkId=gbs[0].id;
  S.importModal=null;
  saveTeams(); R();
  safeAlert(players.length+" joueurs importés !");
}

function exportPlayersCSV(side){
  const t=S[side];
  let csv="Numéro,Nom,Poste\n";
  t.players.forEach(p=>{ csv+=`${p.number},${p.name},${p.position}\n`; });
  const filename=`${t.name.replace(/\s/g,"_")}_effectif.csv`;
  const blob=new Blob([csv],{type:"text/csv"});
  // iPad Safari: use share API if available, else open in new tab
  if(navigator.share && navigator.canShare){
    const file=new File([blob],filename,{type:"text/csv"});
    if(navigator.canShare({files:[file]})){
      navigator.share({files:[file],title:filename}).catch(()=>{});
      return;
    }
  }
  // Fallback: open in new tab (works on iPad)
  const w=window.open("","_blank");
  if(w){ w.document.write("<pre>"+csv+"</pre>"); w.document.title=filename; }
  else { 
    // Last fallback: copy to clipboard
    navigator.clipboard.writeText(csv).then(()=>safeAlert("CSV copié dans le presse-papier !")).catch(()=>safeAlert(csv));
  }
}

let timerInterval=null;
function startTimer(){ if(S.running||S.readOnly)return; S.running=true; timerInterval=setInterval(()=>{S.time++;renderTimer();},1000); upsertMatchSnapshot(); R();}
function stopTimer(){ if(S.readOnly)return; S.running=false; clearInterval(timerInterval); upsertMatchSnapshot(); R();}
function resetTimer(){ if(S.readOnly)return; stopTimer(); S.time=0; R();}
function fmtTime(t){ const m=Math.floor(t/60),s=t%60; return String(m).padStart(2,"0")+":"+String(s).padStart(2,"0"); }
function renderTimer(){ const el=document.getElementById("tmr"); if(el) el.textContent=fmtTime(S.time); }

// ═══════════════════════════════════════════════════════
// MATCH LOGIC
// ═══════════════════════════════════════════════════════
function autoValidatePending(){
  const ap=S.actionPanel;
  if(!ap || !ap.type || !ACTIONS[ap.type]) return;
  if(ap && ap.shooterId){
    validateAndClose();
  }
  S.actionPanel=null;
}

function selectAction(type){
  if(S.readOnly) return;
  if(S.penMode) return;
  autoValidatePending();
  S.penResultSelect = null;
  S.selectedAction = S.selectedAction===type ? null : type;
  S.playerSelect = null;
  R();
}


function clickTeam(team){
  if(S.readOnly) return;
  if(S.penMode) return;
  if(!S.selectedAction) return;
  autoValidatePending();
  S._lastTeam = team;
  if(S.selectedAction==='PEN'){
    S.penResultSelect = {team};
    R(); return;
  }
  if(S.selectedAction==='TM'){
    // Record TM event directly, no player needed
    S.events.unshift({
      id:gid(), type:"TM", team, time:fmtTime(S.time), rawTime:S.time,
      period:S.period, x:null, y:null, gkId:null,
      playerId:null, playerName:null, playerNumber:null,
      assistId:null, assistName:null, assistNumber:null, goalZone:null,
    });
    queueEventForSync(S.events[0]);
    // Update TM counters for home team only
    if(team==="home"){
      const mtKey=S.period===1?"mt1":"mt2";
      S.tmUsed[mtKey]++;
    }
    S.selectedAction=null;
    S.actionPanel=null;
    stopTimer();
    const side=team==="home"?S.home.name:S.away.name;
    showToast("⏸ Temps mort "+side);
    R(); return;
  }
  S.actionPanel = {type:S.selectedAction, team, shooterId:null, pdId:null, mapX:null, mapY:null, goalZone:null};
  R();
}

function clickActionPlayer(playerId){
  if(S.readOnly) return;
  // Possession-based: create actionPanel on first player tap
  if(!S.actionPanel){
    if(!S.selectedAction) return;
    autoValidatePending();
    S.actionPanel={type:S.selectedAction, team:S.possession, shooterId:null, pdId:null, mapX:null, mapY:null, goalZone:null};
  }
  const ap=S.actionPanel;
  if(S.penMode && !ap.type){
    // Étape "3 boutons" du pénalty (désignation ou réassignation du tireur, y compris après
    // une remise à zéro par la revalidation du tireur, STORY-33 P1-4) — jamais de validation ici,
    // et jamais d'accès à ACTIONS[ap.type] puisque ap.type est intentionnellement null à ce stade.
    ap.shooterId = (ap.shooterId===playerId) ? null : playerId;
    R(); return;
  }
  const act=ACTIONS[ap.type];
  if(!ap.shooterId){
    ap.shooterId=playerId;
    // PO: record player, activate penMode, open the on-court outcome panel
    if(ap.type==='PEN_OBT'){
      const team=ap.team;
      validateAndClose();              // enregistre le PEN_OBT, inchangé — événement définitif, indépendant de l'issue qui suivra
      S.penMode=true;
      S.actionPanel={type:null, team, shooterId:playerId, pdId:null, mapX:null, mapY:null, goalZone:null};
      R(); return;
    }
    // Shot actions (GOAL/SAVE/OFF): switch to position or goal zone mode
    if(act.isGoal||act.isSave||act.isOff){
      R(); return; // renderMatchPanel handles the next step display
    }
    // All other actions: instant validate after player tap
    validateAndClose(); R(); return;
  } else if(ap.shooterId===playerId){
    ap.shooterId=null;
  } else {
    ap.shooterId=playerId;
  }
  R();
}

function clickGoalZone(zone){
  if(S.readOnly) return;
  const ap=S.actionPanel; if(!ap) return;
  ap.goalZone = ap.goalZone===zone ? null : zone;
  const act=ACTIONS[ap.type];
  if(S.trackGK && ap.shooterId && (act.isGoal||act.isSave||act.isOff)){
    if(ap.mapX==null) ap.mapX=50;
    validateAndClose(); R(); return;
  }
  R();
}

function clickCourtPosition(x,y){
  if(S.readOnly) return;
  const ap=S.actionPanel; if(!ap||!ap.shooterId) return;
  const act=ACTIONS[ap.type];
  ap.mapX=x; ap.mapY=y;
  // Tir non cadré : pas de zone de but à demander, il n'y a pas d'impact dans le but par définition
  if(!S.trackGK || act.isOff){ validateAndClose(); }
  R();
}

function choosePenOutcome(kind){          // kind: 'GOAL' | 'SAVE' | 'OFF'
  if(S.readOnly) return;
  const ap=S.actionPanel; if(!ap||!ap.shooterId) return;
  const penMap={GOAL:'PEN_GOAL',SAVE:'PEN_SAVE',OFF:'PEN_OFF'};
  ap.type=penMap[kind];
  ap.mapX=50; ap.mapY=85;                 // position fixe, comme aujourd'hui
  const act=ACTIONS[ap.type];
  if(!S.trackGK || act.isOff){
    validateAndClose();                   // validation immédiate — même règle que pour un tir normal (clickCourtPosition())
  }
  R();
}

function closePenPanel(){
  if(S.readOnly) return;
  S.actionPanel=null;
  S.selectedAction=null;
  S.penMode=false;
  R();
}

function recordTM(team){
  if(S.readOnly) return;
  if(team==="home"){
    const mtKey=S.period===1?"mt1":"mt2";
    if(S.tmUsed[mtKey]>=2||S.tmUsed.mt1+S.tmUsed.mt2>=3){
      showToast("Plus de temps mort disponible !", true); return;
    }
    S.tmUsed[mtKey]++;
  }
  S.events.unshift({
    id:gid(), type:"TM", team, time:fmtTime(S.time), rawTime:S.time,
    period:S.period, x:null, y:null, gkId:null,
    playerId:null, playerName:null, playerNumber:null,
    assistId:null, assistName:null, assistNumber:null, goalZone:null,
  });
  queueEventForSync(S.events[0]);
  checkGkConsecutiveAlert(); checkTimeoutAdvisor(); R();
}

function clickActionMap(x,y){
  if(S.readOnly) return;
  const ap=S.actionPanel; if(!ap) return;
  ap.mapX=Math.round(x); ap.mapY=Math.round(y);
  // Auto-validate non-shot actions (PB, PO, JF) when player + map position set
  const act=ACTIONS[ap.type];
  if(ap.shooterId && !act.isGoal && !act.isSave && !act.isOff){
    validateActionPanel();
    return;
  }
  R();
}

// Timeout advisor - checks patterns and suggests TM
function checkTimeoutAdvisor(){
  const now=Date.now();
  // Don't spam: at least 30s between suggestions
  if(now - S.tmLastAlert < 30000) return;
  const used=S.tmUsed.mt1+S.tmUsed.mt2;
  if(used>=3) return; // no TM left
  const mtKey=S.period===1?"mt1":"mt2";
  if(S.tmUsed[mtKey]>=2) return; // no TM left this half

  // Rule 1: 3 home attacks without scoring + adversary scores 2+ during that stretch
  let homeAttacksWithout=0, awayGoalsDuring=0;
  for(const e of S.events){
    if((e.period||1)!==S.period) break; // current period only
    if(e.team==="home"){
      if(ACTIONS[e.type]?.isGoal){ break; } // home scored, reset
      if(ACTIONS[e.type]?.isSave || ACTIONS[e.type]?.isOff || e.type==="TURNOVER"){
        homeAttacksWithout++;
      }
    } else if(e.team==="away"){
      if(ACTIONS[e.type]?.isGoal) awayGoalsDuring++;
    }
  }
  if(homeAttacksWithout>=3 && awayGoalsDuring>=2){
    S.tmLastAlert=now;
    showToast("💡 3 attaques sans marquer + "+awayGoalsDuring+" buts adverses → Temps mort conseillé !", true);
    return;
  }

  // Rule 2: 3 consecutive PB (turnovers) from home
  let consecutivePB=0;
  for(const e of S.events){
    if((e.period||1)!==S.period) break; // current period only
    if(e.team!=="home") continue;
    if(e.type==="TURNOVER"){
      consecutivePB++;
    } else {
      break; // any other home action resets
    }
  }
  if(consecutivePB>=3){
    S.tmLastAlert=now;
    showToast("💡 "+consecutivePB+" PB d'affilée → Temps mort conseillé !", true);
    return;
  }
}

// Check if home GK has consecutive goals conceded and show live alert
function checkGkConsecutiveAlert(){
  // Look at recent events (newest first) against home GK - current period only
  let consecutive=0;
  let prevGk=null;
  for(const e of S.events){
    if((e.period||1)!==S.period) break; // stop at period boundary
    if(e.team==="home" && e.type==="TM") break; // TM resets consecutive streak
    if(e.team!=="away") continue;
    if(!ACTIONS[e.type]?.isGoal && !ACTIONS[e.type]?.isSave) continue;
    // GK change resets
    if(prevGk && e.gkId && e.gkId!==prevGk) break;
    prevGk=e.gkId;
    if(ACTIONS[e.type]?.isGoal){
      consecutive++;
    } else {
      break; // save resets
    }
  }
  const tmLeft=3-S.tmUsed.mt1-S.tmUsed.mt2;
  if(consecutive>=3 && consecutive<5){
    if(tmLeft>0) showToast("💡 "+consecutive+" buts encaissés de suite → Temps mort conseillé !", true);
  } else if(consecutive===5){
    showToast("⚠️ 5 buts encaissés de suite ! Changez de GB !", true);
  } else if(consecutive>5 && (consecutive-5)%2===0){
    showToast("🚨 "+consecutive+" buts encaissés de suite ! Changez de GB !", true);
  }
}

function validateActionPanel(){
  if(S.readOnly) return;
  const ap=S.actionPanel; if(!ap || !ap.shooterId) return;
  const act = ACTIONS[ap.type];
  const oppTeam = ap.team==="home"?"away":"home";
  const gk = S[oppTeam].gkId;
  const player = S[ap.team].players.find(p=>p.id===ap.shooterId);
  const pdPlayer = ap.pdId ? S[ap.team].players.find(p=>p.id===ap.pdId) : null;

  if(ap._editIdx!=null && S.events[ap._editIdx]){
    // Editing existing event
    const ev=S.events[ap._editIdx];
    ev.type=ap.type; ev.team=ap.team;
    ev.x=ap.mapX; ev.y=ap.mapY;
    ev.gkId=(act.isGoal||act.isSave||act.isOff)?gk:null;
    ev.playerId=ap.shooterId;
    ev.playerName=player?player.name:null;
    ev.playerNumber=player?player.number:null;
    ev.assistId=ap.pdId||null;
    ev.assistName=pdPlayer?pdPlayer.name:null;
    ev.assistNumber=pdPlayer?pdPlayer.number:null;
    ev.goalZone=ap.goalZone||null;
    queueEventForSync(ev);
  } else {
    // New event
    S.events.unshift({
      id:gid(), type:ap.type, team:ap.team, time:fmtTime(S.time), rawTime:S.time,
      period:S.period, x:ap.mapX, y:ap.mapY,
      gkId: (act.isGoal||act.isSave||act.isOff) ? gk : null,
      playerId: ap.shooterId,
      playerName: player ? player.name : null,
      playerNumber: player ? player.number : null,
      assistId: ap.pdId||null,
      assistName: pdPlayer ? pdPlayer.name : null,
      assistNumber: pdPlayer ? pdPlayer.number : null,
      goalZone: ap.goalZone||null,
    });
    queueEventForSync(S.events[0]);
  }

  if(ap._editIdx!=null){
    S.actionPanel = null;
    S.selectedAction = null;
  } else {
    // Keep panel open for potential corrections, but mark as editing event[0]
    ap._editIdx = 0;
  }
  S.pendingPlayer = null;
  S.penResultSelect = null;
  checkGkConsecutiveAlert();
  checkTimeoutAdvisor();
  R();
}

// Called by autoValidatePending: validate and fully close
function validateAndClose(){
  if(S.readOnly) return;
  const ap=S.actionPanel; if(!ap || !ap.shooterId) return;
  const act = ACTIONS[ap.type];
  if(!act) return;
  if(act.isPen && ap._editIdx==null){
    const shooterStillValid = S[ap.team].players.some(p=>p.id===ap.shooterId && p.selected);
    if(!shooterStillValid){
      ap.shooterId=null; ap.type=null; ap.mapX=null; ap.mapY=null; ap.goalZone=null;
      showToast("Le tireur désigné n'est plus disponible, resélectionne un joueur.", true);
      R();
      return;
    }
  }
  const oppTeam = ap.team==="home"?"away":"home";
  const gk = S[oppTeam].gkId;
  const player = S[ap.team].players.find(p=>p.id===ap.shooterId);
  const pdPlayer = ap.pdId ? S[ap.team].players.find(p=>p.id===ap.pdId) : null;

  if(ap._editIdx!=null && S.events[ap._editIdx]){
    const ev=S.events[ap._editIdx];
    ev.type=ap.type; ev.team=ap.team;
    ev.x=ap.mapX; ev.y=ap.mapY;
    ev.gkId=(act.isGoal||act.isSave||act.isOff)?gk:null;
    ev.playerId=ap.shooterId;
    ev.playerName=player?player.name:null;
    ev.playerNumber=player?player.number:null;
    ev.assistId=ap.pdId||null;
    ev.assistName=pdPlayer?pdPlayer.name:null;
    ev.assistNumber=pdPlayer?pdPlayer.number:null;
    ev.goalZone=ap.goalZone||null;
    queueEventForSync(ev);
  } else {
    S.events.unshift({
      id:gid(), type:ap.type, team:ap.team, time:fmtTime(S.time), rawTime:S.time,
      period:S.period, x:ap.mapX, y:ap.mapY,
      gkId: (act.isGoal||act.isSave||act.isOff) ? gk : null,
      playerId: ap.shooterId,
      playerName: player ? player.name : null,
      playerNumber: player ? player.number : null,
      assistId: ap.pdId||null,
      assistName: pdPlayer ? pdPlayer.name : null,
      assistNumber: pdPlayer ? pdPlayer.number : null,
      goalZone: ap.goalZone||null,
    });
    queueEventForSync(S.events[0]);
  }
  // Auto-switch possession after shots and turnovers
  if(!ap._editIdx && (act.isGoal||act.isSave||act.isOff||ap.type==="TURNOVER")){
    S.possession = ap.team==="home"?"away":"home";
  }
  if(act.isPen && (act.isGoal||act.isSave||act.isOff)) S.penMode=false;
  S.actionPanel = null;
  S.selectedAction = null;
  S.pendingPlayer = null;
  S.penResultSelect = null;
  checkGkConsecutiveAlert();
  checkTimeoutAdvisor();
}

// Legacy recordEvent for 2min/red badge flow (uses old playerSelect/shotOverlay)
function selectPlayerForAction(playerId){
  const ps = S.playerSelect; if(!ps) return;
  const act = ACTIONS[ps.type];
  S.pendingPlayer = playerId;
  if(act.needsMap){
    S.shotOverlay = {type:ps.type, team:ps.team, playerId};
    S.playerSelect = null;
    R(); return;
  }
  recordEvent(ps.type, ps.team, null, null, playerId);
  S.playerSelect = null;
}

function recordEvent(type, team, x, y, playerId){
  if(S.readOnly) return;
  const act = ACTIONS[type];
  const oppTeam = team==="home"?"away":"home";
  const gk = S[oppTeam].gkId;
  const player = S[team].players.find(p=>p.id===playerId);
  S.events.unshift({
    id:gid(), type, team, time:fmtTime(S.time), rawTime:S.time,
    period:S.period, x:x??null, y:y??null,
    gkId: (act.isGoal||act.isSave||act.isOff) ? gk : null,
    playerId: playerId||null,
    playerName: player ? player.name : null,
    playerNumber: player ? player.number : null,
  });
  queueEventForSync(S.events[0]);
  S.shotOverlay = null;
  S.selectedAction = null;
  S.playerSelect = null;
  S.pendingPlayer = null;
  S.penResultSelect = null;
  R();
}

