function undoLast(){
  if(S.readOnly) return;
  if(S.events.length===0) return;
  if(S.events[0]?.type==='PEN_OBT'){
    S.penMode=false;
    S.actionPanel=null;
    S.selectedAction=null;
  }
  const removed=S.events.shift();
  dequeueEventSync(removed);
  S.pdSelect=false;
  R();
}

// Computed stats
function teamScore(team){
  return S.events.filter(e=>e.team===team && (ACTIONS[e.type].isGoal)).length;
}
function teamStat(team, type){
  return S.events.filter(e=>e.team===team && e.type===type).length;
}
function teamPoss(team){
  return S.events.filter(e=>e.team===team && (ACTIONS[e.type]?.isGoal||ACTIONS[e.type]?.isSave||ACTIONS[e.type]?.isOff||e.type==="TURNOVER")).length;
}
function gkStats(gkId){
  if(!gkId) return {saves:0,goals:0,offs:0,total:0,totalAll:0,pct:"-",pctAll:"-",penSaves:0,penGoals:0,penOffs:0,penTotal:0,penPct:"-"};
  const saves = S.events.filter(e=>e.gkId===gkId && ACTIONS[e.type].isSave && !ACTIONS[e.type].isPen).length;
  const goals = S.events.filter(e=>e.gkId===gkId && ACTIONS[e.type].isGoal && !ACTIONS[e.type].isPen).length;
  const offs = S.events.filter(e=>e.gkId===gkId && ACTIONS[e.type].isOff && !ACTIONS[e.type].isPen).length;
  const penSaves = S.events.filter(e=>e.gkId===gkId && e.type==='PEN_SAVE').length;
  const penGoals = S.events.filter(e=>e.gkId===gkId && e.type==='PEN_GOAL').length;
  const penOffs = S.events.filter(e=>e.gkId===gkId && e.type==='PEN_OFF').length;
  const total = saves+goals; // GK pure: only cadrés
  const totalAll = saves+goals+offs; // team efficiency: all shots
  const penTotal = penSaves+penGoals+penOffs;
  return {
    saves, goals, offs, total, totalAll,
    pct: total>0?Math.round(saves/total*100)+"%":"-",
    pctAll: totalAll>0?Math.round(saves/totalAll*100)+"%":"-",
    penSaves, penGoals, penOffs, penTotal, penPct: penTotal>0?Math.round(penSaves/penTotal*100)+"%":"-"
  };
}
function gkStatsCombined(gkIds){
  if(gkIds.length===0) return gkStats(null);
  if(gkIds.length===1) return gkStats(gkIds[0]);
  const combined = {saves:0,goals:0,offs:0,penSaves:0,penGoals:0,penOffs:0};
  gkIds.forEach(id=>{
    const g=gkStats(id);
    combined.saves+=g.saves; combined.goals+=g.goals; combined.offs+=g.offs;
    combined.penSaves+=g.penSaves; combined.penGoals+=g.penGoals; combined.penOffs+=g.penOffs;
  });
  const total=combined.saves+combined.goals;
  const totalAll=total+combined.offs;
  const penTotal=combined.penSaves+combined.penGoals+combined.penOffs;
  return {
    ...combined, total, totalAll,
    pct: total>0?Math.round(combined.saves/total*100)+"%":"-",
    pctAll: totalAll>0?Math.round(combined.saves/totalAll*100)+"%":"-",
    penTotal, penPct: penTotal>0?Math.round(combined.penSaves/penTotal*100)+"%":"-"
  };
}
function selectedGbs(side){
  return S[side].players.filter(p=>p.position==="GB"&&p.selected);
}
function teamShots(team){
  return S.events.filter(e=>e.team===team && (ACTIONS[e.type].needsMap) && e.x!=null);
}
function goalZoneHeatmap(shots, width){
  const w=width||"80%";
  const ZONES=["HG","HC","HD","MG","MC","MD","BG","BC","BD"];
  const counts={}; ZONES.forEach(z=>counts[z]={goals:0,saves:0,offs:0,total:0});
  shots.forEach(s=>{
    const z=s.goalZone; if(!z||!counts[z]) return;
    counts[z].total++;
    if(ACTIONS[s.type]?.isGoal) counts[z].goals++;
    else if(ACTIONS[s.type]?.isSave) counts[z].saves++;
    else counts[z].offs++;
  });
  const maxC=Math.max(...ZONES.map(z=>counts[z].total),1);
  return `<div style="font-style:italic;font-size:10px;color:var(--t3);text-align:center;width:${w};margin:0 auto 3px;">Stat des tireurs (ex : 1/1 = 1 but et non arrêt)</div>
  <div style="display:grid;grid-template-columns:1fr 1fr 1fr;grid-template-rows:1fr 1fr 1fr;gap:1px;width:${w};margin:0 auto;aspect-ratio:5/2;border-radius:4px 4px 0 0;overflow:hidden;border:2px solid var(--border);border-bottom:3px solid var(--fenix-sky);">
    ${ZONES.map(z=>{
      const c=counts[z]; const opacity=c.total>0?(.2+.8*(c.total/maxC)):0;
      const gPct=c.total>0?c.goals/c.total:0;
      const bg=c.total>0?
        (gPct>.5?`rgba(80,200,120,${opacity})`:`rgba(78,205,232,${opacity})`):
        "var(--bg3)";
      return `<div style="display:flex;align-items:center;justify-content:center;font-size:16px;font-weight:700;background:${bg};color:${c.total>0?"#fff":"var(--t3)"};">${c.total>0?`${c.goals}/${c.total}`:""}</div>`;
    }).join("")}
  </div>`;
}
function getPlayer(team, id){
  return S[team].players.find(p=>p.id===id);
}
function gkName(team){
  const gk = S[team].gkId;
  if(!gk) return "Non sélectionné";
  const p = getPlayer(team, gk);
  return p ? `${p.number?"#"+p.number+" ":""}${p.name}` : "?";
}

// Save match
// Safe alert/confirm - fallback to toast in restricted environments
function safeAlert(msg){
  try{ window.alert(msg); }catch(e){ showToast(msg); }
}
function safeConfirm(msg){
  try{ return window.confirm(msg); }catch(e){ return true; }
}
function showToast(msg, isAlert){
  const t=document.createElement("div");
  const bg=isAlert?"rgba(232,70,90,.95)":"#1A2840";
  const border=isAlert?"2px solid #FF3344":"1px solid #7BA7C2";
  const size=isAlert?"15px":"13px";
  t.style.cssText=`position:fixed;top:20px;left:50%;transform:translateX(-50%);background:${bg};color:#fff;padding:${isAlert?"16px 24px":"12px 20px"};border-radius:10px;border:${border};z-index:9999;font-size:${size};font-weight:${isAlert?"800":"400"};max-width:85vw;text-align:center;box-shadow:0 4px 20px rgba(0,0,0,.5);`;
  t.textContent=msg;
  document.body.appendChild(t);
  const dur=isAlert?4000:2500;
  setTimeout(()=>{t.style.opacity="0";t.style.transition="opacity .3s";setTimeout(()=>{try{document.body.removeChild(t);}catch(e){}},400);},dur);
}

// Download CSV - with fallback for restricted environments (Claude HTML viewer)
const _isRestricted = (window.self !== window.top) || document.referrer.includes('claude');
function downloadFile(content, filename, mimeType){
  if(_isRestricted){
    showExportModal(content, filename);
    return;
  }
  try{
    const blob = new Blob([content], {type: mimeType || "text/csv;charset=utf-8;"});
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = filename;
    a.style.display = "none";
    document.body.appendChild(a);
    a.click();
    setTimeout(()=>{
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
    }, 500);
  }catch(e){
    showExportModal(content, filename);
  }
}

function showExportModal(content, filename){
  const div=document.createElement("div");
  div.style.cssText="position:fixed;top:0;left:0;width:100vw;height:100vh;background:rgba(0,0,0,.85);z-index:9999;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:20px;";
  div.innerHTML=`
    <div style="background:#1A2840;border-radius:12px;padding:16px;width:90%;max-width:500px;max-height:80vh;display:flex;flex-direction:column;gap:8px;">
      <div style="display:flex;justify-content:space-between;align-items:center;">
        <span style="color:#7BA7C2;font-weight:700;">📤 ${filename}</span>
        <button id="_export_close" style="background:none;border:1px solid #555;color:#ccc;border-radius:6px;padding:4px 10px;cursor:pointer;">✕</button>
      </div>
      <div style="color:#aaa;font-size:12px;">Sélectionne tout et copie (⌘A puis ⌘C)</div>
      <textarea id="_export_text" style="flex:1;min-height:200px;background:#0D1B2A;color:#fff;border:1px solid #333;border-radius:6px;padding:8px;font-size:11px;font-family:monospace;resize:none;" readonly></textarea>
      <button id="_export_copy" style="background:#7BA7C2;color:#fff;border:none;border-radius:6px;padding:10px;font-weight:700;cursor:pointer;font-size:14px;">📋 Copier dans le presse-papier</button>
    </div>`;
  document.body.appendChild(div);
  const ta=div.querySelector("#_export_text");
  ta.value=content;
  div.querySelector("#_export_close").onclick=()=>document.body.removeChild(div);
  div.querySelector("#_export_copy").onclick=()=>{
    ta.select(); ta.setSelectionRange(0,999999);
    navigator.clipboard.writeText(content).then(()=>{
      div.querySelector("#_export_copy").textContent="✅ Copié !";
      setTimeout(()=>document.body.removeChild(div),1200);
    }).catch(()=>{
      try{document.execCommand("copy");div.querySelector("#_export_copy").textContent="✅ Copié !";}catch(e){}
    });
  };
  div.onclick=(e)=>{if(e.target===div) document.body.removeChild(div);};
}

function exportMatchCSV(){
  const rows=[["type","team","time","period","x","y","playerId","playerName","playerNumber","gkId","assistId","assistName","assistNumber","goalZone"]];
  rows.push(["#META",S.home.name,S.away.name,S.time,S.period,teamScore("home"),teamScore("away"),new Date().toISOString(),S.season,S.journee]);
  // Players rows
  ["home","away"].forEach(side=>{
    S[side].players.filter(p=>p.selected).forEach(p=>{
      rows.push(["#PLAYER",side,p.id,p.name,p.number,p.position,p.id===S[side].gkId?"GK_ACTIVE":""]);
    });
  });
  // Events (newest first in array, export oldest first for readability)
  [...S.events].reverse().forEach(ev=>{
    rows.push([ev.type,ev.team,ev.time,ev.period,ev.x??"",ev.y??"",
      ev.playerId||"",ev.playerName||"",ev.playerNumber||"",ev.gkId||"",
      ev.assistId||"",ev.assistName||"",ev.assistNumber||"",ev.goalZone||""]);
  });
  const csv=rows.map(r=>r.join(";")).join("\n");
  const d=new Date().toISOString().slice(0,10);
  downloadFile(csv, `match_${S.home.name}_vs_${S.away.name}_${d}.csv`);
}

function importMatchCSV(){
  if(S.readOnly) return;
  const input=document.createElement("input");
  input.type="file"; input.accept=".csv";
  input.style.display="none";
  document.body.appendChild(input);
  input.onchange=e=>{
    const file=e.target.files[0]; if(!file){ document.body.removeChild(input); return; }
    const reader=new FileReader();
    reader.onload=ev=>{
      try{
        const lines=ev.target.result.split("\n").map(l=>l.trim()).filter(l=>l);
        // Skip header
        let metaFound=false;
        const events=[];
        const players={home:[],away:[]};
        let gkIds={home:null,away:null};
        lines.forEach(line=>{
          const cols=line.split(";");
          if(cols[0]==="#META"){
            S.home.name=cols[1]||S.home.name;
            S.away.name=cols[2]||S.away.name;
            S.time=parseInt(cols[3])||0;
            S.period=parseInt(cols[4])||1;
            if(cols[8]) S.season=cols[8];
            if(cols[9]) S.journee=cols[9];
            metaFound=true;
          } else if(cols[0]==="#PLAYER"){
            const side=cols[1];
            const p={id:cols[2],name:cols[3],number:cols[4],position:cols[5],selected:true};
            players[side].push(p);
            if(cols[6]==="GK_ACTIVE") gkIds[side]=cols[2];
          } else if(cols[0]!==""&&cols[0]!=="type"&&!cols[0].startsWith("#")){
            events.push({
              id:gid(), type:cols[0], team:cols[1], time:cols[2], period:parseInt(cols[3])||1,
              rawTime:0, x:cols[4]?parseInt(cols[4]):null, y:cols[5]?parseInt(cols[5]):null,
              playerId:cols[6]||null, playerName:cols[7]||null, playerNumber:cols[8]||null,
              gkId:cols[9]||null, assistId:cols[10]||null, assistName:cols[11]||null, assistNumber:cols[12]||null,
              goalZone:cols[13]||null,
            });
          }
        });
        if(!metaFound){safeAlert("Fichier CSV invalide"); return;}
        // Apply players if found
        ["home","away"].forEach(side=>{
          if(players[side].length>0) S[side].players=players[side];
          if(gkIds[side]) S[side].gkId=gkIds[side];
        });
        S.events=events.reverse(); // newest first
        saveTeams();
        safeAlert(`Match importé: ${S.home.name} vs ${S.away.name} (${events.length} événements)`);
        R();
      }catch(err){ safeAlert("Erreur d'import: "+err.message); }
      document.body.removeChild(input);
    };
    reader.readAsText(file);
  };
  input.click();
}

// ─── EXPORT / IMPORT ALL MATCHES ───
async function exportAllMatches(){
  let matches;
  // Filtre par equipe active (STORY-50) : "Tout exporter" doit rester borne a ce que l'ecran
  // Matchs affiche reellement, jamais inclure a l'insu de l'utilisateur les matchs de l'autre
  // equipe (particulierement sensible pour -18, cf. docs/risks/deux-equipes.md R0).
  try{ const all=await dbGetAll(); matches=all.filter(m=>(m.teamProfile||"cf")===(S.teamProfile||"cf")); }catch(e){ safeAlert("Erreur lecture base"); return; }
  if(matches.length===0){ safeAlert("Aucun match à exporter"); return; }
  
  const SEP=";;;---MATCH_SEPARATOR---;;;";
  const parts=[];
  matches.forEach(m=>{
    const rows=[];
    rows.push(["#META",m.home?.name||"",m.away?.name||"",m.time||0,m.period||1,m.scoreH??0,m.scoreA??0,m.date||"",m.season||"",m.journee||"",m.id||0].join(";"));
    ["home","away"].forEach(side=>{
      const team=m[side]; if(!team||!team.players) return;
      team.players.filter(p=>p.selected).forEach(p=>{
        rows.push(["#PLAYER",side,p.id,p.name,p.number||"",p.position||"?",p.id===team.gkId?"GK_ACTIVE":""].join(";"));
      });
    });
    const evts=m.events||[];
    [...evts].reverse().forEach(ev=>{
      rows.push([ev.type,ev.team,ev.time,ev.period,ev.x??"",ev.y??"",
        ev.playerId||"",ev.playerName||"",ev.playerNumber||"",ev.gkId||"",
        ev.assistId||"",ev.assistName||"",ev.assistNumber||"",ev.goalZone||""].join(";"));
    });
    parts.push(rows.join("\n"));
  });
  
  const csv=parts.join("\n"+SEP+"\n");
  downloadFile(csv, `fenix_all_matches_${new Date().toISOString().slice(0,10)}.csv`);
  safeAlert(`${matches.length} match(s) exporté(s)`);
}

async function importAllMatches(){
  const input=document.createElement("input");
  input.type="file"; input.accept=".csv";
  input.style.display="none";
  document.body.appendChild(input);
  input.onchange=async e=>{
    const file=e.target.files[0]; if(!file){ document.body.removeChild(input); return; }
    const reader=new FileReader();
    reader.onload=async ev=>{
      try{
        const SEP=";;;---MATCH_SEPARATOR---;;;";
        const text=ev.target.result;
        const blocks=text.split(SEP).map(b=>b.trim()).filter(b=>b);
        let count=0;
        for(const block of blocks){
          const lines=block.split("\n").map(l=>l.trim()).filter(l=>l);
          // teamProfile tague sur l'equipe active au moment de l'import (pas un fallback "cf"
          // par defaut) — un import fait depuis le profil -18 doit rester visible sous -18.
          let match={events:[],home:{name:"?",players:[],gkId:null},away:{name:"?",players:[],gkId:null},teamProfile:S.teamProfile||"cf"};
          const events=[];
          
          for(const line of lines){
            const cols=line.split(";");
            if(cols[0]==="#META"){
              match.home.name=cols[1]||"?";
              match.away.name=cols[2]||"?";
              match.time=parseInt(cols[3])||0;
              match.period=parseInt(cols[4])||1;
              match.scoreH=parseInt(cols[5])||0;
              match.scoreA=parseInt(cols[6])||0;
              match.date=cols[7]||"";
              match.season=cols[8]||"";
              match.journee=cols[9]||"";
              match.id=parseInt(cols[10])||Date.now()+Math.random()*1000|0;
            } else if(cols[0]==="#PLAYER"){
              const side=cols[1];
              if(side==="home"||side==="away"){
                const p={id:cols[2],name:cols[3],number:cols[4]||"",position:cols[5]||"?",selected:true};
                match[side].players.push(p);
                if(cols[6]==="GK_ACTIVE") match[side].gkId=cols[2];
              }
            } else if(cols[0]&&cols[0]!=="type"&&!cols[0].startsWith("#")){
              events.push({
                id:gid(), type:cols[0], team:cols[1], time:cols[2], period:parseInt(cols[3])||1,
                rawTime:0, x:cols[4]?parseInt(cols[4]):null, y:cols[5]?parseInt(cols[5]):null,
                playerId:cols[6]||null, playerName:cols[7]||null, playerNumber:cols[8]||null,
                gkId:cols[9]||null, assistId:cols[10]||null, assistName:cols[11]||null, assistNumber:cols[12]||null,
                goalZone:cols[13]||null,
              });
            }
          }
          match.events=events.reverse();
          await dbSaveMatch(match);
          count++;
        }
        { const all=await dbGetAll(); S.matchHistory=all.filter(m=>(m.teamProfile||"cf")===(S.teamProfile||"cf")); }
        safeAlert(`${count} match(s) importé(s)`);
        R();
      }catch(err){ safeAlert("Erreur d'import: "+err.message); }
      document.body.removeChild(input);
    };
    reader.readAsText(file);
  };
  input.click();
}

async function saveMatch(){
  if(S.readOnly) return;
  const match={
    id:Date.now(),
    date:new Date().toLocaleDateString("fr-FR",{day:"numeric",month:"short",year:"numeric",hour:"2-digit",minute:"2-digit"}),
    season:S.season, journee:S.journee, championnat:S.championnat||"",
    teamProfile:S.teamProfile||"cf", // STORY-50 — scope l'historique par equipe
    home:{...S.home,players:S.home.players.map(p=>({...p}))},
    away:{...S.away,players:S.away.players.map(p=>({...p}))},
    events:[...S.events], time:S.time, period:S.period,
    scoreH:teamScore("home"), scoreA:teamScore("away"),
    coachNotes:S.coachNotes||"",
    supabaseMatchId:S.currentMatchId||null, // pour pouvoir supprimer aussi côté Supabase si ce match est effacé plus tard
  };
  try{
    await dbSaveMatch(match);
    const count=await dbGetAll().then(a=>a.filter(m=>(m.teamProfile||"cf")===(S.teamProfile||"cf")).length).catch(()=>0);
    // Auto-reparation (trouve suite a un incident reel, cf. docs/brief-v15-diagnostic-sync-multi-appareil.md) :
    // markMatchFinishedById() ne fait que des update() -- si la ligne Supabase n'a jamais existe
    // (ex. toutes les tentatives upsertMatchSnapshot() du match ont echoue silencieusement pour
    // une raison quelconque, colonne manquante ou reseau), la marquer "finished" est un no-op
    // silencieux et le match reste coince localement, invisible sur les autres appareils. Un
    // upsertMatchSnapshot() de secours ici cree la ligne si besoin (upsert, pas update) avant de
    // la marquer terminee -- rend la sauvegarde auto-reparatrice plutot que de propager l'incident.
    await upsertMatchSnapshot();
    await markMatchFinished();
    safeAlert("✅ Match sauvegardé !\n\n💾 "+count+" match(s) en mémoire.\n\n📥 Pensez à exporter le CSV de temps en temps\n(onglet Matchs → Export CSV)");
  }catch(e){ safeAlert("Erreur de sauvegarde: "+e.message); }
  R();
}

// Marque un match Supabase comme terminé, pour qu'il arrête d'apparaître comme "reprenable"
async function markMatchFinishedById(matchId){
  const client=initSupabaseClient();
  if(!client||!matchId) return;
  try{ await client.from('matches').update({status:'finished'}).eq('id',matchId); }catch(e){}
  // Appel separe, volontairement (STORY-48/49/50) : si season/journee/coach_notes/championnat
  // n'existent pas encore cote Supabase (migration pas encore executee), PostgREST rejette tout
  // l'appel pour colonne inconnue — separe du statut 'finished' ci-dessus, un oubli de migration
  // ne degrade que l'enrichissement, jamais le comportement deja en production (le match qui
  // arrete de s'afficher comme "reprenable" sur les autres appareils).
  try{ await client.from('matches').update({season:S.season, journee:S.journee, coach_notes:S.coachNotes||"", championnat:S.championnat||""}).eq('id',matchId); }catch(e){}
}
async function markMatchFinished(){ return markMatchFinishedById(S.currentMatchId); }

// Abandonne un match proposé comme "reprenable" (écran de reprise) — le marque terminé côté
// Supabase (les données/événements déjà saisis restent disponibles, juste plus proposé au
// démarrage) et le retire immédiatement de la liste affichée.
async function discardResumableMatch(matchId){
  if(!safeConfirm("Abandonner ce match ? Il ne sera plus proposé au démarrage. Les données déjà saisies restent conservées sur Supabase.")) return;
  await markMatchFinishedById(matchId);
  S.resumePrompt=(S.resumePrompt||[]).filter(m=>m.id!==matchId);
  R();
}

// Supprime réellement un match sur Supabase (ligne matches + tous ses match_events) — best-effort,
// appelé quand un match sauvegardé est supprimé localement. Les match_events doivent être supprimés
// avant la ligne matches (pas de ON DELETE CASCADE dans le schéma, cf. docs/supabase-setup.sql).
async function deleteSupabaseMatch(matchId){
  const client=initSupabaseClient();
  if(!client||!matchId) return;
  try{
    await client.from('match_events').delete().eq('match_id',matchId);
    await client.from('matches').delete().eq('id',matchId);
  }catch(e){ /* best-effort : la suppression Supabase peut échouer hors-ligne, pas de retry dédié */ }
}

function newMatch(){
  if(S.readOnly) return;
  if(!safeConfirm("Nouveau match ? Les stats en cours seront perdues si non sauvegardées.")) return;
  stopTimer();
  // Appelé AVANT tout reset ci-dessous : markMatchFinished() pousse season/journee/coach_notes/
  // championnat encore actuels (STORY-48/49/50) vers l'ancien match Supabase — l'appeler après
  // les resets lui ferait hériter à tort de la journée/du championnat du PROCHAIN match.
  markMatchFinished(); // l'ancien match ne doit plus apparaître comme "reprenable" une fois abandonné
  // Increment journée
  const jNum=parseInt(S.journee.replace(/\D/g,""))||0;
  S.events=[]; S.time=0; S.period=1; S.selectedAction=null; S.shotOverlay=null;
  S.playerSelect=null; S.pendingPlayer=null; S.penResultSelect=null; S.pdSelect=false;
  S.actionPanel=null; S.penMode=false;
  S.tmUsed={mt1:0,mt2:0}; S.tmLastAlert=0; S.coachNotes="";
  S.gkFilter={home:"all",away:"all"}; S.gkShotFilter={goals:true,saves:true,offs:true};
  S.journee="J"+(jNum+1);
  S.championnat=""; // reinitialise a chaque match (STORY-50), jamais persiste comme S.season — evite qu'un "Amical" oublie contamine le match suivant
  S.away.name="Adversaire";
  S.currentMatchId=null; // nouveau match = nouvel id Supabase, régénéré à la volée au premier événement
  unsubscribeMatchEvents();
  R();
}

// Charge un match archivé comme match courant — utilisée par le bouton "📂 Charger" de
// l'Historique (data-load-match) ET le raccourci PDF de Bilan (data-load-match-pdf, STORY-36).
// opts.gotoView/gotoStatsTab permettent au raccourci PDF d'atterrir directement sur Stats→PDF ;
// opts.confirmContext="pdf-bilan" quantifie le texte de confirmation pour ce point d'entrée précis.
function loadMatchAsCurrent(id, opts={}){
  if(S.readOnly) return false;
  const m=S.matchHistory.find(x=>x.id===id); if(!m) return false;

  let msg = `Charger ${m.home?.name} vs ${m.away?.name} (${m.journee||""}) ?\nLe match en cours sera remplacé.`;
  if(opts.confirmContext==="pdf-bilan" && S.events.length>0){
    msg = `⚠️ Vous avez un match EN COURS avec ${S.events.length} événement(s) non sauvegardé(s).\nLe charger effacera ${S.events.length} action(s) déjà saisies.\nCharger ${m.home?.name} vs ${m.away?.name} (${m.journee||""}) à la place ?`;
  }
  if(!safeConfirm(msg)) return false;

  // ─── P0 — couper tout lien avec le match en cours AVANT de charger le match archivé,
  // symétrique à newMatch() : sinon la souscription Realtime encore active écrirait les
  // événements/snapshots du match archivé vers le matchId Supabase du vrai match en cours.
  S.currentMatchId = null;
  unsubscribeMatchEvents();

  S.home={...m.home,players:(m.home?.players||[]).map(p=>({...p}))};
  S.away={...m.away,players:(m.away?.players||[]).map(p=>({...p}))};
  S.events=(m.events||[]).map(e=>({...e}));
  S.time=m.time||0; S.period=m.period||1;
  S.season=m.season||S.season; S.journee=m.journee||S.journee;
  S.coachNotes=m.coachNotes||"";
  S.selectedAction=null; S.shotOverlay=null; S.playerSelect=null;
  S.penResultSelect=null; S.pdSelect=false; S.actionPanel=null; S.penMode=false;
  S.gkFilter={home:"all",away:"all"}; S.gkShotFilter={goals:true,saves:true,offs:true};
  S.tmUsed={mt1:0,mt2:0};
  S.events.filter(e=>e.type==="TM"&&e.team==="home").forEach(e=>{
    if((e.period||1)===1) S.tmUsed.mt1++; else S.tmUsed.mt2++;
  });
  S.view = opts.gotoView || "match";
  if(opts.gotoStatsTab) S.statsTab = opts.gotoStatsTab;
  saveTeams(); R();
  return true;
}

