// ─── SHOT MAP OVERLAY ───
// ─── PLAYER SELECT OVERLAY (COURT VIEW) ───
// Terrain dessiné en SVG natif (remplace l'ancienne image raster COURT_IMG).
// Référentiel conservé : viewBox 0 0 350 208, identique à l'ancien système de
// coordonnées x/y des événements déjà enregistrés. Échelle ~17.5 unités/mètre
// (350 unités = 20m de large), but en haut (y=0).
// Géométrie officielle : la zone (6m) et la ligne des 9m ne sont PAS des
// demi-cercles centrés sur le milieu du but — ce sont deux quarts de cercle
// centrés sur chaque poteau (rayon 6m / 9m), reliés par un segment droit de
// la largeur du but. Le rayon 9m dépasse la distance poteau→ligne de touche,
// donc l'arc des 9m rejoint la ligne de touche, pas la ligne de but.
function courtSvgMarkup(){
  return `
    <rect x="0" y="0" width="350" height="208" fill="var(--court-fill)"/>
    <line x1="0" y1="207" x2="350" y2="207" stroke="var(--court-line)" stroke-width="1" opacity=".5"/>
    <line x1="0" y1="1" x2="0" y2="208" stroke="var(--court-line)" stroke-width="1" opacity=".5"/>
    <line x1="350" y1="1" x2="350" y2="208" stroke="var(--court-line)" stroke-width="1" opacity=".5"/>
    <line x1="175" y1="0" x2="175" y2="208" stroke="var(--court-line)" stroke-width="1" stroke-dasharray="2,3" opacity=".4"/>
    <path d="M 43.75,1 A 105,105 0 0 0 148.75,105 L 201.25,105 A 105,105 0 0 0 306.25,1" fill="none" stroke="var(--court-line)" stroke-width="1.5"/>
    <path d="M 0,51.76 A 157.5,157.5 0 0 0 148.75,157.5 L 201.25,157.5 A 157.5,157.5 0 0 0 350,51.76" fill="none" stroke="var(--court-line-dash)" stroke-width="1.5" stroke-dasharray="5,4"/>
    <line x1="168" y1="122.5" x2="182" y2="122.5" stroke="var(--court-line)" stroke-width="2"/>
    <line x1="170" y1="70" x2="180" y2="70" stroke="var(--court-line)" stroke-width="2"/>
    <line x1="148.75" y1="1" x2="201.25" y2="1" stroke="var(--court-goal)" stroke-width="3"/>
  `;
}

// ═══ Zones de tir sur le terrain (bascule points/zones, STORY-43) ═══
// Modele valide par Romain via un prototype visuel reel (8 iterations) avant
// tout code applicatif — cf. docs/arch/zones-terrain-et-tableau-joueurs.md.
// Classe un tir (x/y en %, meme repere que S.events[].x/.y) en zone de
// depart sur le terrain. N'utilise le rayon 6m (R6) nulle part : le disque
// des 6m est trop proche des poteaux pour qu'un point de touche y tombe
// (poteau->touche = 148.75 > 105), donc la vraie frontiere de zone est R9
// partout ; la ligne des 6m (deja tracee par courtSvgMarkup()) reste un pur
// repere visuel, pas une frontiere.
// Portee des ailes, en unites viewBox (350x208) — constante partagee entre
// shotZoneCourt() et buildCourtZones() pour eviter qu'elles divergent (deja
// arrive une fois). Agrandie une 4e fois : des tirs reellement pres du corner
// en usage reel (pas seulement en donnees de test synthetiques) tombaient
// encore hors du triangle aile et etaient classes en 6mG/6mD par erreur.
const COURT_WING_AY=80, COURT_WING_AX=100;
function shotZoneCourt(xPct, yPct){
  const X=xPct/100*350, Y=yPct/100*208;
  const postL=148.75, postR=201.25, R9=157.5;
  const AY=COURT_WING_AY, AX=COURT_WING_AX;
  const centerHalfW=postR-postL, splitL=175-centerHalfW, splitR=175+centerHalfW;
  if(Y<=0) return X<AX?"AILG":(X>350-AX?"AILD":"6MC");
  if(X<AX && Y < AY*(1-X/AX)) return "AILG";
  if(X>350-AX && Y < AY*(1-(350-X)/AX)) return "AILD";
  if(X>=splitL && X<=splitR){
    let boundary;
    if(X>=postL && X<=postR) boundary=R9;
    else { const post=X<postL?postL:postR, dx=Math.abs(X-post); boundary=Math.sqrt(Math.max(0,R9*R9-dx*dx)); }
    return Y<boundary ? "6MC" : "9MC";
  }
  const post=X<splitL?postL:postR, dir=X<splitL?-1:1;
  const dx=Math.abs(X-post), r=Math.hypot(dx,Y);
  if(r<R9) return dir<0?"6MG":"6MD";
  return dir<0?"9MG":"9MD";
}
const COURT_ZONE_ORDER=["AILG","6MG","6MC","6MD","AILD","9MG","9MC","9MD"];
// Positions de texte pre-calculees par zone en % (pas le centroide brut, qui
// tombe mal sur les zones en arc/concaves). 6mG/6mD deplaces entre les
// lignes 6m et 9m (retour Romain, usage reel) ; 6mC volontairement laisse
// entre 4m et 6m (rester "entre 6m/9m" le mettrait pile sur le marqueur 7m,
// confusion directe) ; AILG/AILD/9m* inchanges.
const COURT_ZONE_LABEL_POS={
  AILG:[5.1,7.7], AILD:[94.9,7.7],
  "6MG":[26.3,58], "6MC":[50,41.8], "6MD":[73.7,58],
  "9MG":[10,85.6], "9MC":[50,88], "9MD":[90,85.6]
};
let _courtZonesCache=null;
// Genere les 8 polygones de zone une seule fois (memoise — ne depend d'aucune
// donnee de match), points en % (0-100), conversion vers viewBox (x3.5,
// x2.08) faite au moment du rendu par renderCourtZones(), pas ici.
function buildCourtZones(){
  if(_courtZonesCache) return _courtZonesCache;
  const VBW=350, postL=148.75, postR=201.25, R9=157.5;
  const AY=COURT_WING_AY, AX=COURT_WING_AX;
  const toPct=(X,Y)=>({x:X/VBW*100, y:Y/208*100});
  function arcPoints(post, dir, radius, angleFrom, angleTo, steps=24){
    const pts=[];
    for(let i=0;i<=steps;i++){
      const a=(angleFrom+(angleTo-angleFrom)*i/steps)*Math.PI/180;
      pts.push(toPct(post+dir*radius*Math.cos(a), radius*Math.sin(a)));
    }
    return pts;
  }
  const touchAngle=Math.acos(postL/R9)*180/Math.PI;
  const touchY=R9*Math.sin(touchAngle*Math.PI/180);
  const farY=207; // ligne de touche basse deja tracee par courtSvgMarkup() a Y=207
  const centerHalfW=postR-postL, splitL=175-centerHalfW, splitR=175+centerHalfW;
  function angleAtX(post,X,radius){ return Math.acos(Math.abs(post-X)/radius)*180/Math.PI; }
  const angleSplitL=angleAtX(postL,splitL,R9), angleSplitR=angleAtX(postR,splitR,R9);
  const ySplit=R9*Math.sin(angleSplitL*Math.PI/180);
  const z={};
  z.AILG=[toPct(0,0),toPct(0,AY),toPct(AX,0)];
  z.AILD=[toPct(VBW,0),toPct(VBW,AY),toPct(VBW-AX,0)];
  z['6MG']=[toPct(AX,0),toPct(splitL,0),toPct(splitL,ySplit), ...arcPoints(postL,-1,R9,angleSplitL,touchAngle), toPct(0,AY)];
  z['6MC']=[toPct(splitL,0),toPct(splitR,0), ...arcPoints(postR,1,R9,angleSplitR,90), toPct(postR,R9),toPct(postL,R9), ...arcPoints(postL,-1,R9,90,angleSplitL)];
  z['6MD']=[toPct(VBW-AX,0),toPct(splitR,0),toPct(splitR,ySplit), ...arcPoints(postR,1,R9,angleSplitR,touchAngle), toPct(VBW,AY)];
  z['9MG']=[toPct(0,touchY), ...arcPoints(postL,-1,R9,touchAngle,angleSplitL), toPct(splitL,farY),toPct(0,farY)];
  z['9MC']=[toPct(splitL,ySplit), ...arcPoints(postL,-1,R9,angleSplitL,90), toPct(postL,R9),toPct(postR,R9), ...arcPoints(postR,1,R9,90,angleSplitR), toPct(splitR,ySplit),toPct(splitR,farY),toPct(splitL,farY)];
  z['9MD']=[toPct(VBW,touchY), ...arcPoints(postR,1,R9,touchAngle,angleSplitR), toPct(splitR,farY),toPct(VBW,farY)];
  _courtZonesCache=z;
  return z;
}
function aggregateCourtZones(shots){
  const data={}; COURT_ZONE_ORDER.forEach(z=>data[z]={g:0,t:0});
  shots.forEach(s=>{
    const z=shotZoneCourt(s.x,s.y);
    if(!data[z]) return;
    data[z].t++; if(s.goal) data[z].g++;
  });
  return data;
}
// Rendu SVG des zones de tir + marqueur 7m, a superposer a courtSvgMarkup()
// (memes reperes 6m/9m/4m/7m deja traces par cette derniere, pas redessines
// ici). shots: [{x,y,goal}] en %. penData: {g,t} sur les evenements
// PEN_GOAL/PEN_SAVE/PEN_OFF (jamais x/y, l'origine d'un 7m est toujours le
// meme point). Marqueur "Sans GB" volontairement absent ici : necessite une
// nouvelle capture live non construite (cf. docs/arch/), afficher un badge
// en permanence vide serait un faux repere plutot qu'une aide.
function renderCourtZones(shots, penData){
  const zones=buildCourtZones();
  const data=aggregateCourtZones(shots);
  const toVB=p=>({x:p.x*3.5, y:p.y*2.08});
  const polys=COURT_ZONE_ORDER.map(z=>{
    const pts=zones[z].map(p=>{const v=toVB(p); return v.x+","+v.y;}).join(" ");
    const d=data[z];
    const fill=d.t===0?"var(--bg3)":(d.g/d.t>0.5?"rgba(80,200,120,.85)":"rgba(78,205,232,.85)");
    return `<polygon points="${pts}" fill="${fill}" stroke="var(--court-line)" stroke-width=".6" stroke-linejoin="round"/>`;
  }).join("");
  const labels=COURT_ZONE_ORDER.map(z=>{
    const d=data[z]; if(d.t===0) return "";
    const p=COURT_ZONE_LABEL_POS[z], v=toVB({x:p[0],y:p[1]});
    return `<text x="${v.x}" y="${v.y}" style="font-size:9px;font-weight:800;fill:#fff;text-anchor:middle;dominant-baseline:middle;paint-order:stroke;stroke:rgba(0,0,0,.45);stroke-width:1.6px;">${d.g}/${d.t}</text>`;
  }).join("");
  const pen=penData||{g:0,t:0};
  const penColor=pen.t===0?"var(--bg3)":(pen.g/pen.t>0.5?"#50C878":"#4ECDE8");
  const penMarker=`<circle cx="175" cy="122.5" r="11" fill="${penColor}" stroke="var(--panel)" stroke-width="1.2"/>`+
    (pen.t>0
      ?`<text x="175" y="126" style="font-size:9px;font-weight:800;fill:#0c1520;text-anchor:middle;">${pen.g}/${pen.t}</text>`
      :`<text x="175" y="125.5" style="font-size:7.5px;font-weight:800;fill:#0c1520;text-anchor:middle;">7m</text>`);
  return polys+labels+penMarker;
}
// Bouton de bascule points/zones, reutilise sur Joueurs/Gardiens/Comparaison
// — un seul etat global S.shotViewMode, pas de reglage par ecran.
function shotViewToggleHtml(){
  const isZones=S.shotViewMode==="zones";
  return `<div class="shotview-toggle">
    <button class="shotview-btn ${!isZones?"on":""}" data-shotview="points" title="Points localises">📍</button>
    <button class="shotview-btn ${isZones?"on":""}" data-shotview="zones" title="Zones du terrain">🗺️</button>
  </div>`;
}

function renderCourtEmptyState(){
  return `<div class="court-empty-msg">
    <div class="icon">👥</div>
    <div>Aucun joueur sélectionné</div>
    <div style="font-size:11px;">Va dans Équipes pour choisir ton effectif</div>
  </div>`;
}

function displayNumber(p){ return p.number ? p.number : "–"; }

// Style CSS d'un encart joueur sur le terrain, à partir de {cx,cy,anchor} produit par
// courtPlayerPositions(). anchor:"left"/"right" ancre le BORD de l'encart (pas son centre,
// donc indépendant de sa largeur — variable selon la longueur du nom) sur la ligne de touche.
function cpBoxStyle(p){
  if(p.anchor==="left") return `left:${p.cx}%;top:${p.cy}%;transform:translateY(-50%);`;
  if(p.anchor==="right") return `right:${100-p.cx}%;top:${p.cy}%;transform:translateY(-50%);`;
  return `left:${p.cx}%;top:${p.cy}%;`;
}

function courtPlayerPositions(roster){
  const groups={};
  roster.forEach(p=>{
    const pos=p.position||"?";
    if(!groups[pos]) groups[pos]=[];
    groups[pos].push(p);
  });
  const result=[];
  Object.entries(groups).forEach(([pos,players])=>{
    const base=POS_XY[pos]||POS_XY["?"];
    const anchor=base.anchor||"center";
    if(players.length===1){
      result.push({...players[0], cx:base.x, cy:base.y, anchor});
    } else if(base.spread==="h"){
      // Spread horizontally. hSpread réglable par position (POS_XY) car des noms
      // longs sur 2 joueurs se chevauchaient avec l'écart par défaut, trop juste
      // pour la largeur réelle des encarts.
      const hSpread=base.hSpread||Math.min(16, 70/players.length);
      players.forEach((p,i)=>{
        const offset=(i-(players.length-1)/2)*hSpread;
        result.push({...p, cx:Math.max(6,Math.min(94,base.x+offset)), cy:base.y, anchor});
      });
    } else if(base.spread==="grid"){
      // Disposition en grille autour de base.x/base.y — triangle à 3 (un joueur
      // devant, centré, deux derrière), carré à 4 (deux de chaque côté). Sert
      // PVT (STORY-38) mais réutilisable par tout poste qui recevrait un jour un
      // effectif similaire. 5+ : pas de disposition dédiée, juste une grille
      // générique à 2 colonnes qui garantit l'absence de chevauchement total.
      const hStep=base.hSpread||26, vStep=base.vSpread||13;
      const layouts={
        2:[{dx:-hStep/2,dy:0},{dx:hStep/2,dy:0}],
        3:[{dx:0,dy:-vStep/2},{dx:-hStep/2,dy:vStep/2},{dx:hStep/2,dy:vStep/2}],
        4:[{dx:-hStep/2,dy:-vStep/2},{dx:hStep/2,dy:-vStep/2},{dx:-hStep/2,dy:vStep/2},{dx:hStep/2,dy:vStep/2}],
      };
      const layout=layouts[players.length];
      if(layout){
        players.forEach((p,i)=>result.push({...p,
          cx:Math.max(6,Math.min(94,base.x+layout[i].dx)),
          cy:Math.max(4,Math.min(96,base.y+layout[i].dy)), anchor}));
      } else {
        const perRow=2, rowCount=Math.ceil(players.length/perRow);
        players.forEach((p,i)=>{
          const row=Math.floor(i/perRow), col=i%perRow;
          const colsInRow=Math.min(perRow, players.length-row*perRow);
          result.push({...p,
            cx:Math.max(6,Math.min(94,base.x+(col-(colsInRow-1)/2)*hStep)),
            cy:Math.max(4,Math.min(96,base.y+(row-(rowCount-1)/2)*vStep)), anchor});
        });
      }
    } else {
      // Spread vertically (GB, ARG, DC, ARD, etc.) — cx reste sur la ligne de touche
      // pour les positions ancrées (ARG/ARD), seule la profondeur (cy) varie.
      const vSpread=13;
      players.forEach((p,i)=>{
        const offset=(i-(players.length-1)/2)*vSpread;
        result.push({...p, cx:base.x, cy:Math.max(4,Math.min(96,base.y+offset)), anchor});
      });
    }
  });
  return result;
}

function renderPlayerSelect(){
  const ps=S.playerSelect;
  const a=ACTIONS[ps.type];
  const team=ps.team;
  const isHome=team==="home";
  const accent=isHome?"var(--fenix-sky)":"var(--red)";
  let roster = S[team].players.filter(p=>p.selected);
  const positioned = courtPlayerPositions(roster);

  return `<div class="ps-overlay" id="ps-overlay">
    <div class="ps-modal" style="width:min(900px,98vw);">
      <h3>${a.icon} ${a.label} — ${S[team].name}</h3>
      <div class="ps-sub">Sélectionne le joueur</div>
      <div class="court-pick">
      <svg class="court-svg-bg" viewBox="0 0 350 208" preserveAspectRatio="none">${courtSvgMarkup()}</svg>
        ${roster.length===0 ? renderCourtEmptyState() : positioned.map(p=>`
          <div class="cp-player" data-pick-player="${p.id}"
               style="${cpBoxStyle(p)}border-color:${accent};">
            <div class="cp-num ${p.number?"":"cp-num-missing"}" style="color:${accent}">${displayNumber(p)}</div>
            <div class="cp-name">${p.name}</div>
          </div>
        `).join("")}
      </div>
      <button class="shot-cancel" id="ps-cancel" style="margin-top:6px;">Annuler</button>
    </div>
  </div>`;
}

