function openFullscreen(cardEl){
  const overlay=document.createElement("div");
  overlay.className="fs-overlay";
  const title=cardEl.querySelector(".card-t")?.textContent||"Détail";
  overlay.innerHTML=`<div class="fs-overlay-header">
    <span style="font-weight:700;color:var(--fenix-sky);font-size:14px;">${title}</span>
    <button class="btn btn-xs" style="font-size:16px;border-color:var(--border);color:var(--t2);padding:6px 14px;" id="fs-close-btn">✕ Fermer</button>
  </div>
  <div class="fs-overlay-body"></div>`;
  const body=overlay.querySelector(".fs-overlay-body");
  const clone=cardEl.cloneNode(true);
  clone.querySelectorAll(".fs-btn").forEach(b=>b.remove());
  
  // Detect tirs subis card (has court SVG viewBox 350x208)
  const courtSvg=clone.querySelector('svg[viewBox="0 0 350 208"]');
  if(courtSvg){
    // Terrain card: stretch content full width
    clone.classList.add("fs-court");
    clone.style.margin="0";
    courtSvg.style.maxWidth="none";
    courtSvg.style.width="100%";
    const heatmap=clone.querySelector('div[style*="grid-template-columns"]');
    if(heatmap){
      heatmap.style.width="85%";
      heatmap.style.maxWidth="600px";
      heatmap.style.aspectRatio="5/2";
      heatmap.style.fontSize="20px";
    }
    body.style.flexDirection="column";
    body.style.alignItems="stretch";
    body.style.padding="12px";
  } else {
    // All other cards: centered with max-width like tirs subis proportions
    clone.style.maxWidth="92%";
    clone.style.width="92%";
    clone.style.margin="0 auto";
    body.style.flexDirection="column";
    body.style.alignItems="center";
    body.style.padding="12px";
    // Enlarge heatmaps if present
    clone.querySelectorAll('div[style*="grid-template-columns"]').forEach(hm=>{
      hm.style.width="85%";
      hm.style.maxWidth="600px";
      hm.style.fontSize="20px";
    });
    // Scale up text for iPad
    clone.querySelectorAll("table").forEach(t=>{t.style.fontSize="16px";});
    clone.querySelectorAll(".compare-row").forEach(r=>{r.style.padding="4px 0";});
    clone.querySelectorAll(".cv-a,.cv-b").forEach(el=>{el.style.fontSize="16px";});
    clone.querySelectorAll(".c-lbl").forEach(el=>{el.style.fontSize="12px";});
    // Scale SVG graphs (evolution)
    clone.querySelectorAll("svg").forEach(svg=>{
      svg.style.width="100%";
      svg.style.maxWidth="none";
    });
  }
  
  body.appendChild(clone);
  document.body.appendChild(overlay);
  overlay.querySelector("#fs-close-btn").onclick=()=>{overlay.remove();};
}

// Mini-terrain agrege par equipe — Stats -> Comparaison (STORY-44). Meme
// bascule/geometrie que Joueurs/Gardiens (STORY-43). Nouveaute locale a cet
// ecran : marqueurs PB (TURNOVER, needsMap deja vrai mais jamais dessine
// ailleurs) — uniquement en mode "points" (un 3e chiffre par zone en mode
// "zones" surchargerait un texte deja dense ; le total PB reste visible via
// la stat d'en-tete quel que soit le mode).
function renderCompareCourt(side){
  const t=S[side]; const color=side==="home"?"var(--green)":"var(--red)";
  const shots=S.events.filter(e=>e.team===side&&(ACTIONS[e.type]?.isGoal||ACTIONS[e.type]?.isSave||ACTIONS[e.type]?.isOff)&&e.x!=null);
  const pbShots=S.events.filter(e=>e.team===side&&e.type==="TURNOVER"&&e.x!=null);
  const goals=shots.filter(s=>ACTIONS[s.type]?.isGoal).length;
  const total=shots.length;
  const pb=teamStat(side,"TURNOVER");
  const penEvts=S.events.filter(e=>e.team===side&&ACTIONS[e.type]?.isPen);
  const penData={g:penEvts.filter(e=>ACTIONS[e.type]?.isGoal).length, t:penEvts.length};
  const zoneShots=shots.map(s=>({x:s.x,y:s.y,goal:!!ACTIONS[s.type]?.isGoal}));
  const isZones=S.shotViewMode==="zones";

  const pointsMarkup=shots.map(s=>{
    const c=ACTIONS[s.type].isGoal?"#50C878":ACTIONS[s.type].isSave?"#E84E5E":"#E89A4E";
    const sx=s.x/100*350, sy=s.y/100*208;
    if(ACTIONS[s.type].isGoal){
      return `<circle cx="${sx}" cy="${sy}" r="4" fill="${c}66" stroke="${c}" stroke-width="1.5"/>`;
    }
    return `<g><circle cx="${sx}" cy="${sy}" r="4" fill="${c}44" stroke="${c}" stroke-width="1"/>`+
      `<line x1="${sx-3}" y1="${sy-3}" x2="${sx+3}" y2="${sy+3}" stroke="${c}" stroke-width="1.5" stroke-linecap="round"/>`+
      `<line x1="${sx+3}" y1="${sy-3}" x2="${sx-3}" y2="${sy+3}" stroke="${c}" stroke-width="1.5" stroke-linecap="round"/></g>`;
  }).join("");
  const pbMarkup=pbShots.map(s=>{
    const c="#E8465A";
    const sx=s.x/100*350, sy=s.y/100*208;
    return `<path d="M ${sx} ${sy-4.5} L ${sx+4.5} ${sy} L ${sx} ${sy+4.5} L ${sx-4.5} ${sy} Z" fill="${c}55" stroke="${c}" stroke-width="1.3"/>`;
  }).join("");

  return `<div class="card" style="position:relative;">
    <button class="fs-btn" title="Plein écran">⛶</button>
    <div style="display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:8px;padding-right:34px;">
      <div class="card-t" style="color:${color};margin-bottom:0;">🥅 ${t.name}</div>
      ${shotViewToggleHtml()}
    </div>
    <div style="display:flex;justify-content:center;gap:20px;margin-bottom:8px;">
      <div style="text-align:center;"><div class="mono" style="font-size:16px;font-weight:800;">${goals}/${total}</div><div style="font-size:9px;color:var(--t2);text-transform:uppercase;letter-spacing:.05em;">Buts/Tirs</div></div>
      <div style="text-align:center;"><div class="mono" style="font-size:16px;font-weight:800;color:var(--red);">${pb}</div><div style="font-size:9px;color:var(--t2);text-transform:uppercase;letter-spacing:.05em;">PB</div></div>
    </div>
    <svg viewBox="0 0 350 208" style="width:100%;max-width:420px;display:block;margin:0 auto;border-radius:6px;border:1px solid var(--border);" xmlns="http://www.w3.org/2000/svg">
      ${courtSvgMarkup()}
      ${isZones ? renderCourtZones(zoneShots, penData) : pointsMarkup+pbMarkup}
    </svg>
    ${!isZones?`<div style="display:flex;justify-content:center;gap:12px;margin-top:6px;font-size:10px;color:var(--t2);flex-wrap:wrap;">
      <span><span style="color:#50C878">●</span> But</span>
      <span><span style="color:var(--red)">✕</span> Arrêté</span>
      <span><span style="color:var(--orange)">✕</span> Hors cadre</span>
      <span><span style="color:var(--red)">◆</span> PB</span>
    </div>`:""}
  </div>`;
}

function renderStatCompare(){
  const hGoals=teamScore("home"), aGoals=teamScore("away");
  // Flags isSave/isOff (pas teamStat exact-match) pour inclure les tirs sur pénalty,
  // comme goals (teamScore, flag isGoal) — cf. matchStats() qui fait déjà pareil.
  const hSaves=S.events.filter(e=>e.team==="home"&&ACTIONS[e.type]?.isSave).length;
  const aSaves=S.events.filter(e=>e.team==="away"&&ACTIONS[e.type]?.isSave).length;
  const hOff=S.events.filter(e=>e.team==="home"&&ACTIONS[e.type]?.isOff).length;
  const aOff=S.events.filter(e=>e.team==="away"&&ACTIONS[e.type]?.isOff).length;
  const hTotal=hGoals+hSaves+hOff, aTotal=aGoals+aSaves+aOff;
  const hEff=hTotal>0?Math.round(hGoals/hTotal*100):0;
  const aEff=aTotal>0?Math.round(aGoals/aTotal*100):0;
  const hGkSaves=teamStat("away","SAVE");
  const aGkSaves=teamStat("home","SAVE");
  const hPoss=teamPoss("home"), aPoss=teamPoss("away");
  const stats = [
    {l:"Buts/Tirs",a:hGoals+"/"+hTotal,b:aGoals+"/"+aTotal,ra:hGoals,rb:aGoals},
    {l:"Pen",a:teamStat("home","PEN_GOAL")+"/"+(teamStat("home","PEN_GOAL")+teamStat("home","PEN_SAVE")+teamStat("home","PEN_OFF")),b:teamStat("away","PEN_GOAL")+"/"+(teamStat("away","PEN_GOAL")+teamStat("away","PEN_SAVE")+teamStat("away","PEN_OFF")),ra:teamStat("home","PEN_GOAL"),rb:teamStat("away","PEN_GOAL")},
    {l:"Efficacité",a:hEff+"%",b:aEff+"%",ra:hEff,rb:aEff},
    {l:"Arrêts GB",a:hGkSaves,b:aGkSaves,ra:hGkSaves,rb:aGkSaves},
    {l:"Non cadrés",a:hOff,b:aOff,ra:hOff,rb:aOff},
    {l:"PB",a:teamStat("home","TURNOVER"),b:teamStat("away","TURNOVER"),ra:teamStat("home","TURNOVER"),rb:teamStat("away","TURNOVER")},
    {l:"Jet franc",a:teamStat("home","FREEKICK"),b:teamStat("away","FREEKICK"),ra:teamStat("home","FREEKICK"),rb:teamStat("away","FREEKICK")},
    {l:"2 min",a:teamStat("home","TWO_MIN"),b:teamStat("away","TWO_MIN"),ra:teamStat("home","TWO_MIN"),rb:teamStat("away","TWO_MIN")},
    {l:"Carton R",a:teamStat("home","RED"),b:teamStat("away","RED"),ra:teamStat("home","RED"),rb:teamStat("away","RED")},
    {l:"Possessions",a:hPoss,b:aPoss,ra:hPoss,rb:aPoss},
  ];
  // Score evolution data - parse time to continuous minutes (MT2 = +30)
  function timeToMin(timeStr, period){
    const parts=(timeStr||"0:00").split(":");
    const m=parseInt(parts[0])||0, s=parseInt(parts[1])||0;
    const base=m+s/60;
    return (period||1)>=2 ? 30+base : base;
  }
  const ef=S.evoFilter||"all"; // "all","mt1","mt2"
  const allGoalEvts=[...S.events].reverse().filter(e=>ACTIONS[e.type]?.isGoal);
  const goalEvts=allGoalEvts.filter(e=>{
    if(ef==="mt1") return (e.period||1)===1;
    if(ef==="mt2") return (e.period||1)===2;
    return true;
  });
  let hRun=0,aRun=0;
  // Starting scores for filtered view
  if(ef==="mt2"){
    allGoalEvts.filter(e=>(e.period||1)===1).forEach(e=>{if(e.team==="home")hRun++;else aRun++;});
  }
  const hStart=hRun, aStart=aRun;
  const minStart=ef==="mt2"?30:0;
  const minEnd=ef==="mt1"?30:60;
  const evoPoints=[{h:hRun,a:aRun,min:minStart,who:null}];
  goalEvts.forEach(e=>{
    if(e.team==="home") hRun++; else aRun++;
    evoPoints.push({h:hRun,a:aRun,min:timeToMin(e.time,e.period||1),who:e.team});
  });
  const maxScore=Math.max(hRun,aRun,1);
  const W=400,H=195,PX=40,PY=15;
  const gW=W-PX-10,gH=H-PY*2-15;
  const minToX=(m)=>PX+(m-minStart)/(minEnd-minStart)*gW;
  const hasMT2=allGoalEvts.some(e=>(e.period||1)===2);
  const htLine=ef==="all"&&hasMT2?`<line x1="${minToX(30)}" y1="${PY}" x2="${minToX(30)}" y2="${PY+gH}" stroke="rgba(240,199,94,.4)" stroke-width="1.5" stroke-dasharray="4,3"/>
    <text x="${minToX(30)}" y="${PY+gH+12}" fill="rgba(240,199,94,.6)" font-size="8" text-anchor="middle">MI-TEMPS</text>`:"";
  // X-axis labels
  const xLabels=[];
  if(ef==="all"){for(let m=0;m<=60;m+=10)xLabels.push(m);}
  else if(ef==="mt1"){for(let m=0;m<=30;m+=5)xLabels.push(m);}
  else{for(let m=30;m<=60;m+=5)xLabels.push(m);}

  const hasTmEvts=S.events.some(e=>e.type==="TM");
  // Tirs par poste
  const positions=["ALG","ARG","DC","ARD","ALD","PVT","GB"];
  const posLabels={ALG:"Aile G",ARG:"Arr. G",DC:"Demi-C",ARD:"Arr. D",ALD:"Aile D",PVT:"Pivot",GB:"GB","?":"Autre"};
  const posShots={};
  ["home","away"].forEach(side=>{
    posShots[side]={};
    S.events.filter(e=>e.team===side&&e.playerId&&(ACTIONS[e.type]?.isGoal||ACTIONS[e.type]?.isSave||ACTIONS[e.type]?.isOff)).forEach(e=>{
      const pl=S[side].players.find(p=>p.id===e.playerId);
      const pos=pl?pl.position:"?";
      if(!posShots[side][pos]) posShots[side][pos]={goals:0,total:0};
      posShots[side][pos].total++;
      if(ACTIONS[e.type]?.isGoal) posShots[side][pos].goals++;
    });
  });
  const posSvg=`<div class="stat-courts" style="margin-top:12px;">
    ${["home","away"].map(side=>{
      const color=side==="home"?"var(--green)":"var(--red)";
      const ps=posShots[side];
      const posKeys=[...positions,"?"].filter(p=>ps[p]);
      if(posKeys.length===0) return "";
      const maxT=Math.max(...posKeys.map(p=>ps[p].total),1);
      return `<div class="card" style="position:relative;">
        <button class="fs-btn" title="Plein écran">⛶</button>
        <div class="card-t" style="color:${color};text-align:center;">🎯 Tirs par poste — ${S[side].name}</div>
        ${posKeys.map(p=>{
          const d=ps[p]; const pct=d.total>0?Math.round(d.goals/d.total*100):0;
          return `<div style="display:flex;align-items:center;gap:8px;margin:4px 0;">
            <span style="width:55px;font-size:10px;font-weight:700;color:var(--t2);text-align:right;">${posLabels[p]||p}</span>
            <div style="flex:1;height:18px;background:rgba(255,255,255,.05);border-radius:4px;position:relative;overflow:hidden;">
              <div style="height:100%;width:${d.total/maxT*100}%;background:rgba(123,167,194,.15);border-radius:4px;"></div>
              <div style="position:absolute;top:0;left:0;height:100%;width:${d.goals/maxT*100}%;background:rgba(123,167,194,.35);border-radius:4px;"></div>
            </div>
            <span class="mono" style="font-size:11px;font-weight:700;width:45px;text-align:center;">${d.goals}/${d.total}</span>
            <span class="mono" style="font-size:11px;font-weight:700;color:var(--yellow);width:35px;text-align:center;">${pct}%</span>
          </div>`;
        }).join("")}
      </div>`;
    }).join("")}
  </div>`;

  const compareCourtSvg=`<div class="stat-courts" style="margin-top:12px;">
    ${["home","away"].map(side=>renderCompareCourt(side)).join("")}
  </div>`;

  return `<div class="compare-evo-row">
    <div class="card" style="position:relative;flex:1;min-width:280px;max-width:none;margin:0;">
      <button class="fs-btn" title="Plein écran">⛶</button>
      <div style="display:flex;justify-content:space-between;margin-bottom:10px;padding-right:34px;">
        <span style="font-weight:700;color:var(--green)">${S.home.name}</span>
        <span style="font-weight:700;color:var(--red)">${S.away.name}</span>
      </div>
      ${stats.map(s=>{
        const t=s.ra+s.rb||1;
        return `<div class="compare-row compare-row-dual">
          <span class="c-lbl-l">${s.l}</span>
          <span class="cv-a mono" style="color:var(--green)">${s.a}</span>
          <div class="c-bar"><div class="ba" style="width:${s.ra/t*100}%"></div><div class="bb" style="width:${s.rb/t*100}%"></div></div>
          <span class="cv-b mono" style="color:var(--red)">${s.b}</span>
          <span class="c-lbl">${s.l}</span>
        </div>`;
      }).join("")}
    </div>
    ${(goalEvts.length>0||hasTmEvts)?`<div class="card" style="position:relative;flex:1;min-width:280px;max-width:none;margin:0;">
      <button class="fs-btn" title="Plein écran">⛶</button>
      <div class="card-t" style="text-align:center;">📈 Évolution du score</div>
      <div style="display:flex;justify-content:center;gap:4px;margin-bottom:6px;">
        <button class="btn btn-xs ${ef==="all"?"btn-g":""}" data-evo-filter="all">Tout</button>
        <button class="btn btn-xs ${ef==="mt1"?"btn-g":""}" data-evo-filter="mt1">MT1</button>
        <button class="btn btn-xs ${ef==="mt2"?"btn-g":""}" data-evo-filter="mt2">MT2</button>
      </div>
      <svg viewBox="0 0 ${W} ${H}" style="width:100%;display:block;" xmlns="http://www.w3.org/2000/svg">
        ${Array.from({length:maxScore-Math.min(hStart,aStart)+1},(_,i)=>{
          const v=Math.min(hStart,aStart)+i;
          if(v>maxScore) return "";
          return `<line x1="${PX}" y1="${PY+gH-v/maxScore*gH}" x2="${W-10}" y2="${PY+gH-v/maxScore*gH}" stroke="rgba(255,255,255,.07)" stroke-width="1"/>
          <text x="${PX-6}" y="${PY+gH-v/maxScore*gH+4}" fill="rgba(255,255,255,.3)" font-size="9" text-anchor="end">${v}</text>`;
        }).join("")}
        ${xLabels.map(m=>`<text x="${minToX(m)}" y="${PY+gH+12}" fill="rgba(255,255,255,.3)" font-size="8" text-anchor="middle">${m}'</text>`).join("")}
        ${htLine}
        <polyline fill="none" stroke="#7BA7C2" stroke-width="2.5" points="${evoPoints.map(p=>`${minToX(p.min)},${PY+gH-p.h/maxScore*gH}`).join(" ")}"/>
        <polyline fill="none" stroke="#E8465A" stroke-width="2.5" points="${evoPoints.map(p=>`${minToX(p.min)},${PY+gH-p.a/maxScore*gH}`).join(" ")}"/>
        ${evoPoints.map(p=>{
          const cx=minToX(p.min);
          let dots="";
          if(p.who==="home"||p.who===null) dots+=`<circle cx="${cx}" cy="${PY+gH-p.h/maxScore*gH}" r="3" fill="#7BA7C2"/>`;
          if(p.who==="away"||p.who===null) dots+=`<circle cx="${cx}" cy="${PY+gH-p.a/maxScore*gH}" r="3" fill="#E8465A"/>`;
          return dots;
        }).join("")}
        ${(()=>{
          const tmEvts=[...S.events].reverse().filter(e=>e.type==="TM").filter(e=>{
            if(ef==="mt1") return (e.period||1)===1;
            if(ef==="mt2") return (e.period||1)===2;
            return true;
          });
          return tmEvts.map(e=>{
            const m=timeToMin(e.time,e.period||1);
            const x=minToX(m);
            const col=e.team==="home"?"#7BA7C2":"#222";
            const stroke=e.team==="home"?"#5A8FAA":"#666";
            return `<rect x="${x-5}" y="${PY+gH+2}" width="10" height="10" rx="2" fill="${col}" stroke="${stroke}" stroke-width="1"/>
              <text x="${x}" y="${PY+gH+9}" fill="#fff" font-size="6" font-weight="700" text-anchor="middle">TM</text>`;
          }).join("");
        })()}
      </svg>
      <div style="display:flex;justify-content:center;gap:16px;font-size:10px;color:var(--t2);margin-top:4px;">
        <span><span style="color:#7BA7C2;">●</span> ${S.home.name}</span>
        <span><span style="color:#E8465A;">●</span> ${S.away.name}</span>
        <span><span style="display:inline-block;width:10px;height:10px;background:#7BA7C2;border-radius:2px;vertical-align:middle;"></span> TM</span>
        <span><span style="display:inline-block;width:10px;height:10px;background:#222;border:1px solid #666;border-radius:2px;vertical-align:middle;"></span> TM adv.</span>
      </div>
    </div>`:""}
  </div>${compareCourtSvg}${posSvg}` + renderGkDetailTables();
}

function renderGkDetailTables(){
  return `<div class="stat-courts" style="margin-top:12px;">
    ${["home","away"].map(side=>{
      const t=S[side]; const color=side==="home"?"var(--green)":"var(--red)";
      const gbs = selectedGbs(side);
      if(gbs.length===0) return `<div class="card"><div class="card-t" style="color:${color}">📋 ${t.name} — Détail GB</div><div style="color:var(--t3);font-size:12px;">Aucun gardien sélectionné</div></div>`;
      return `<div class="card" style="position:relative;">
        <button class="fs-btn" title="Plein écran">⛶</button>
        <div class="card-t" style="color:${color}">📋 ${t.name} — Détail GB</div>
        <div style="overflow-x:auto;">
        <table style="width:100%;border-collapse:collapse;font-size:14px;margin-top:8px;">
          <thead>
            <tr style="border-bottom:1px solid var(--border);color:var(--t2);font-size:11px;text-transform:uppercase;">
              <th style="text-align:left;padding:4px;">Gardien</th>
              <th style="padding:4px;">Arr.</th>
              <th style="padding:4px;">Enc.</th>
              <th style="padding:4px;">H.C.</th>
              <th style="padding:4px;">Arr/Tot</th>
              <th style="padding:4px;">%</th>
              <th style="padding:4px;">Pen</th>
              <th style="padding:4px;">%Pen</th>
            </tr>
          </thead>
          <tbody>
            ${gbs.slice(0,3).map(gb=>{
              const gs=gkStats(gb.id);
              const dn=gb.number?"#"+gb.number+" ":"";
              return `<tr style="border-bottom:1px solid var(--t4);">
                <td style="text-align:left;padding:4px;font-weight:600;">${dn}${gb.name}</td>
                <td class="mono" style="padding:4px;text-align:center;color:var(--blue)">${gs.saves}</td>
                <td class="mono" style="padding:4px;text-align:center;color:var(--red)">${gs.goals}</td>
                <td class="mono" style="padding:4px;text-align:center;color:var(--orange)">${gs.offs}</td>
                <td class="mono" style="padding:4px;text-align:center;">${gs.saves}/${gs.total}</td>
                <td class="mono" style="padding:4px;text-align:center;color:var(--yellow)">${gs.pct}</td>
                <td class="mono" style="padding:4px;text-align:center;color:var(--blue)">${gs.penSaves}/${gs.penTotal}</td>
                <td class="mono" style="padding:4px;text-align:center;color:var(--yellow)">${gs.penPct}</td>
              </tr>`;
            }).join("")}
          </tbody>
        </table>
        </div>
      </div>`;
    }).join("")}
  </div>`;
}

function renderGkSheet(side){
  const t=S[side]; const color=side==="home"?"var(--green)":"var(--red)";
  const oppSide=side==="home"?"away":"home";
  const gbs=selectedGbs(side);
  const filter=S.gkFilter[side];
  const isAll=filter==="all";
  const gk = isAll ? gkStatsCombined(gbs.map(g=>g.id)) : gkStats(filter);
  const accentRgb = side==="home" ? "95,168,211" : "232,70,90";

  // GB selector: dropdown (2+ GB), static label (1 GB), or nothing (0 GB, handled by empty state below)
  let gbSelectorHtml="";
  if(gbs.length>=2){
    gbSelectorHtml=`<select class="gk-filter-select" data-gk-filter-select="${side}" style="color:${side==="home"?"var(--fenix-sky)":"var(--red)"};border:1px solid rgba(${accentRgb},.30);">
      <option value="all" ${isAll?"selected":""}>Tous les GB</option>
      ${gbs.map(gb=>{
        const lbl=(gb.number?"#"+gb.number+" ":"")+gb.name;
        return `<option value="${gb.id}" ${filter===gb.id?"selected":""}>${lbl}</option>`;
      }).join("")}
    </select>`;
  } else if(gbs.length===1){
    const gb=gbs[0];
    gbSelectorHtml=`<div style="font-weight:700;font-size:12px;color:${side==="home"?"var(--fenix-sky)":"var(--red)"};">${(gb.number?"#"+gb.number+" ":"")+gb.name}</div>`;
  }

  // Numbers column: 3-level hierarchy, or empty state if no GK selected
  let numsHtml;
  if(gbs.length===0){
    numsHtml=`<div class="gk-col-empty"><div style="font-size:22px;opacity:.5;">🧤</div><div style="color:var(--t3);font-size:12px;">Aucun gardien sélectionné</div></div>`;
  } else {
    numsHtml=`
      <div class="mono gk-lvl1" style="color:var(--gk-save);">${gk.saves}/${gk.total}</div>
      <div style="font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.08em;color:var(--t2);margin-top:2px;">ARRÊTS</div>
      <div class="mono gk-lvl2" style="color:var(--yellow);margin-top:12px;">${gk.pct}</div>
      <div class="gk-pill-group" style="margin-top:16px;">
        <span class="gk-pill" style="--gk-pill-rgb:80,200,120;"><span class="gk-pill-dot"></span>${gk.goals} encaissés</span>
        <span class="gk-pill" style="--gk-pill-rgb:232,154,78;"><span class="gk-pill-dot"></span>${gk.offs} hors cadre</span>
      </div>`;
  }

  // Court column: heatmap + shot map, filtered by GK selection AND shot-type filter
  const sf=S.gkShotFilter;
  const gkIds = filter==="all" ? gbs.map(g=>g.id) : [filter];
  const allShots = S.events.filter(e=>e.team===oppSide && (ACTIONS[e.type].needsMap) && !ACTIONS[e.type].isPen && e.x!=null && gkIds.includes(e.gkId));
  const shots = allShots.filter(s=>{
    if(ACTIONS[s.type].isGoal) return sf.goals;
    if(ACTIONS[s.type].isSave) return sf.saves;
    if(ACTIONS[s.type].isOff) return sf.offs;
    return true;
  });
  const goals=allShots.filter(s=>ACTIONS[s.type].isGoal).length;
  const saves=allShots.filter(s=>ACTIONS[s.type].isSave).length;
  const offs=allShots.filter(s=>ACTIONS[s.type].isOff).length;

  // Zones de tir (STORY-43) — meme filtre gkIds/type que les points deja
  // affiches ; PEN_* a part (jamais x/y, toujours au point de 7m).
  const penEvts=S.events.filter(e=>e.team===oppSide && ACTIONS[e.type]?.isPen && gkIds.includes(e.gkId));
  const penData={g:penEvts.filter(e=>ACTIONS[e.type]?.isGoal).length, t:penEvts.length};
  const zoneShots=shots.map(s=>({x:s.x,y:s.y,goal:!!ACTIONS[s.type]?.isGoal}));

  const courtHtml=`
    ${goalZoneHeatmap(allShots,"88%")}
    <svg viewBox="0 0 350 208" style="width:100%;max-width:420px;display:block;margin:6px auto 0;border-radius:6px;border:1px solid var(--border);" xmlns="http://www.w3.org/2000/svg">
      ${courtSvgMarkup()}
      ${S.shotViewMode==="zones" ? renderCourtZones(zoneShots, penData) : shots.map(s=>{
        const c = ACTIONS[s.type].isSave?"#4ECDE8":ACTIONS[s.type].isGoal?"#50C878":"#E89A4E";
        const sx=s.x/100*350, sy=s.y/100*208;
        if(ACTIONS[s.type].isGoal){
          return `<circle cx="${sx}" cy="${sy}" r="3" fill="${c}55" stroke="${c}" stroke-width="1"/>`;
        }
        return `<g>
          <circle cx="${sx}" cy="${sy}" r="3" fill="${c}44" stroke="${c}" stroke-width="1"/>
          <line x1="${sx-2}" y1="${sy-2}" x2="${sx+2}" y2="${sy+2}" stroke="${c}" stroke-width="1.5" stroke-linecap="round"/>
          <line x1="${sx+2}" y1="${sy-2}" x2="${sx-2}" y2="${sy+2}" stroke="${c}" stroke-width="1.5" stroke-linecap="round"/>
        </g>`;
      }).join("")}
    </svg>
    <div style="display:flex;justify-content:center;gap:14px;margin-top:8px;">
      <div style="text-align:center;${sf.saves?"":"opacity:.3"}"><div class="mono" style="font-size:22px;font-weight:800;color:var(--green)">${saves}</div><div style="font-size:11px;color:var(--t2)">ARRÊTÉS</div></div>
      <div style="text-align:center;${sf.goals?"":"opacity:.3"}"><div class="mono" style="font-size:22px;font-weight:800;color:var(--red)">${goals}</div><div style="font-size:11px;color:var(--t2)">ENCAISSÉS</div></div>
      <div style="text-align:center;${sf.offs?"":"opacity:.3"}"><div class="mono" style="font-size:22px;font-weight:800;color:var(--orange)">${offs}</div><div style="font-size:11px;color:var(--t2)">H. CADRE</div></div>
    </div>`;

  return `<div class="card gk-sheet" style="position:relative;--gk-accent-rgb:${accentRgb};">
    <button class="fs-btn" title="Plein écran">⛶</button>
    <div style="display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:10px;padding-right:34px;">
      <div class="card-t" style="color:${color};margin-bottom:0;">🧤 ${t.name}</div>
      <div style="display:flex;align-items:center;gap:8px;">
        ${shotViewToggleHtml()}
        ${gbSelectorHtml}
      </div>
    </div>
    <div class="gk-sheet-body">
      <div class="gk-sheet-nums fade-in">${numsHtml}</div>
      <div class="gk-sheet-court fade-in">${courtHtml}</div>
    </div>
  </div>`;
}

